INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11001, 'តាមរូបភាព គណនាចម្ងាយ \(d\) រវាងពីរចំណុច \(A(1, 2)\) និង \(B(5, 5)\) ក្នុងប្លង់កូអរដោនេ៖', 'g10-ee7726487a.svg', '["\\(7\\)", "\\(5\\)", "\\(\\sqrt{7}\\)", "\\(4\\)"]', 1, NULL, 1, 'mcq', '\(d = \sqrt{(5-1)^2 + (5-2)^2} = \sqrt{4^2 + 3^2} = \sqrt{25} = 5\)។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11002, 'កូអរដោនេនៃចំណុចកណ្ដាល \(M\) នៃអង្កត់ \(AB\) ដែល \(A(2, 4)\) និង \(B(6, 8)\) គឺ៖', NULL, '["\\((4, 4)\\)", "\\((2, 2)\\)", "\\((4, 6)\\)", "\\((8, 12)\\)"]', 2, NULL, 1, 'mcq', '\(x_M = \dfrac{2+6}{2} = 4, \quad y_M = \dfrac{4+8}{2} = 6 \implies M(4, 6)\)។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-1edb28e096.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11003, 'តាមរូបភាព ទីប្រជុំទម្ងន់ \(G\) នៃត្រីកោណ \(ABC\) ដែល \(A(2, 6), B(-1, 1), C(5, 2)\) មានកូអរដោនេ៖', 'g10-1edb28e096.svg', '["\\((6, 9)\\)", "\\((2, 2)\\)", "\\((2, 3)\\)", "\\((3, 3)\\)"]', 2, NULL, 1, 'mcq', '\(x_G = \dfrac{2 + (-1) + 5}{3} = 2, \quad y_G = \dfrac{6 + 1 + 2}{3} = 3 \implies G(2, 3)\)។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11004, 'រូបមន្តរកកូអរដោនេនៃចំណុច \(P(x, y)\) ចែកអង្កត់ \(AB\) ខាងក្នុងតាមផលធៀប \(m : n\) គឺ៖', NULL, '["\\(\\left(\\dfrac{mx_B + nx_A}{m+n}, \\dfrac{my_B + ny_A}{m+n}\\right)\\)", "\\(\\left(\\dfrac{x_A + x_B}{m+n}, \\dfrac{y_A + y_B}{m+n}\\right)\\)", "\\(\\left(\\dfrac{mx_A + nx_B}{m+n}, \\dfrac{my_A + ny_B}{m+n}\\right)\\)", "\\(\\left(\\dfrac{mx_B - nx_A}{m-n}, \\dfrac{my_B - ny_A}{m-n}\\right)\\)"]', 0, NULL, 1, 'mcq', 'នេះជារូបមន្តចែកអង្កត់ខាងក្នុងតាមផលធៀប m : n។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11005, 'ដើម្បីឱ្យបីចំណុច \(A, B, C\) រត់ត្រង់ជួរគ្នា លក្ខខណ្ឌចាំបាច់និងគ្រប់គ្រាន់គឺ៖', NULL, '["\\(\\text{មេគុណប្រាប់ទិស } m_{AB} = m_{BC}\\)", "\\(AB + BC = AC^2\\)", "\\(\\vec{AB} \\cdot \\vec{BC} = 0\\)", "\\(x_A + x_B + x_C = 0\\)"]', 0, NULL, 1, 'mcq', 'បីចំណុចរត់ត្រង់ជួរគ្នាកាលណាមេគុណប្រាប់ទិសនៃបន្ទាត់កាត់តាមពីរចំណុចនីមួយៗស្មើគ្នា។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11006, 'ផ្ទៃក្រឡា \(S\) នៃត្រីកោណ \(OAB\) ដែលមានកំពូលមួយនៅគល់កូអរដោនេ \(O(0,0)\), \(A(x_A, y_A)\), \(B(x_B, y_B)\) គិតតាមរូបមន្ត៖', NULL, '["\\(S = \\dfrac{1}{2}|x_A y_B - x_B y_A|\\)", "\\(S = |x_A y_A - x_B y_B|\\)", "\\(S = \\sqrt{x_A^2 + y_B^2}\\)", "\\(S = \\dfrac{1}{2}(x_A y_B + x_B y_A)\\)"]', 0, NULL, 1, 'mcq', 'រូបមន្តផ្ទៃក្រឡាត្រីកោណមានកំពូលមួយនៅគល់កូអរដោនេគឺ \(S = \frac{1}{2}|x_A y_B - x_B y_A|\)។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11007, 'ចម្ងាយពីចំណុច \(P(-3, 4)\) ទៅគល់កូអរដោនេ \(O(0, 0)\) ស្មើនឹង៖', NULL, '["\\(\\sqrt{7}\\)", "\\(7\\)", "\\(5\\)", "\\(1\\)"]', 2, NULL, 1, 'mcq', '\(OP = \sqrt{(-3)^2 + 4^2} = \sqrt{9 + 16} = \sqrt{25} = 5\)។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11008, 'ចំណុច \(I(3, 2)\) ជាចំណុចកណ្ដាលនៃអង្កត់ \(AB\)។ បើ \(A(1, -2)\) នោះកូអរដោនេនៃ \(B\) គឺ៖', NULL, '["\\((2, 0)\\)", "\\((5, 6)\\)", "\\((5, 2)\\)", "\\((4, 2)\\)"]', 1, NULL, 1, 'mcq', '\(x_B = 2x_I - x_A = 2(3) - 1 = 5\) និង \(y_B = 2y_I - y_A = 2(2) - (-2) = 6\)។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11009, 'ត្រីកោណ \(ABC\) មានទីប្រជុំទម្ងន់នៅគល់កូអរដោនេ \(O(0, 0)\)។ បើ \(A(1, 4)\) និង \(B(2, -1)\) នោះចំណុច \(C\) គឺ៖', NULL, '["\\((-3, -3)\\)", "\\((3, 3)\\)", "\\((0, 3)\\)", "\\((-1, -3)\\)"]', 0, NULL, 1, 'mcq', '\(x_C = 3(0) - 1 - 2 = -3\) និង \(y_C = 3(0) - 4 - (-1) = -3\)។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11010, 'គណនាចម្ងាយរវាងចំណុច \(M(2, -1)\) និង \(N(2, 5)\)៖', NULL, '["\\(4\\)", "\\(6\\)", "\\(5\\)", "\\(\\sqrt{26}\\)"]', 1, NULL, 1, 'mcq', 'ដោយអាប់ស៊ីសដូចគ្នា \(x = 2\) នោះ \(MN = |y_N - y_M| = |5 - (-1)| = 6\)។', 'កូអរដោនេនៃចំណុច', 'easy', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-ed1b29164f.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11011, 'តាមរូបភាព រកកូអរដោនេនៃចំណុច \(P\) ដែលចែកអង្កត់ \(AB\) ខាងក្នុងតាមផលធៀប \(AP : PB = 2 : 1\) ដោយ \(A(-2, 1)\) និង \(B(4, 7)\)៖', 'g10-ed1b29164f.svg', '["\\((0, 3)\\)", "\\((3, 6)\\)", "\\((1, 4)\\)", "\\((2, 5)\\)"]', 3, NULL, 2, 'mcq', '\(x_P = \dfrac{2(4) + 1(-2)}{2+1} = \dfrac{6}{3} = 2, \quad y_P = \dfrac{2(7) + 1(1)}{2+1} = \dfrac{15}{3} = 5\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-c809197419.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11012, 'តាមរូបភាព \(ABCD\) ជាប្រលេឡូក្រាមដែលមាន \(A(1, 1), B(5, 2), C(6, 6)\)។ កូអរដោនេកំពូល \(D(x, y)\) គឺ៖', 'g10-c809197419.svg', '["\\((2, 5)\\)", "\\((2, 4)\\)", "\\((1, 6)\\)", "\\((3, 5)\\)"]', 0, NULL, 2, 'mcq', 'អង្កត់ទ្រូងទាំងពីរកាត់គ្នាត្រង់ចំណុចកណ្ដាល \(M\) នាំឱ្យ \(A + C = B + D\) ដូច្នេះ \(x_D = 1 + 6 - 5 = 2\) និង \(y_D = 1 + 6 - 2 = 5\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-67c799a207.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11013, 'តាមរូបភាព គណនាផ្ទៃក្រឡាត្រីកោណ \(ABC\) ដែលមានកំពូល \(A(1, 2), B(6, 3), C(3, 7)\)៖', 'g10-67c799a207.svg', '["\\(11.5\\)", "\\(23\\)", "\\(9.5\\)", "\\(13.5\\)"]', 0, NULL, 2, 'mcq', '\(S = \dfrac{1}{2}|1(3-7) + 6(7-2) + 3(2-3)| = \dfrac{1}{2}|-4 + 30 - 3| = \dfrac{23}{2} = 11.5\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11014, 'រកតម្លៃ \(k\) ដើម្បីឱ្យបីចំណុច \(A(1, 2), B(3, k), C(5, 8)\) រត់ត្រង់ជួរគ្នា៖', NULL, '["\\(6\\)", "\\(3\\)", "\\(5\\)", "\\(4\\)"]', 2, NULL, 2, 'mcq', 'មេគុណប្រាប់ទិសស្មើគ្នា ៖ \(\dfrac{k-2}{3-1} = \dfrac{8-2}{5-1} \implies \dfrac{k-2}{2} = \dfrac{6}{4} = \dfrac{3}{2} \implies k - 2 = 3 \implies k = 5\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11015, 'ចំណុច \(M(x, 0)\) នៅលើអ័ក្សអាប់ស៊ីស មានចម្ងាយស្មើគ្នាពី \(A(-1, 2)\) និង \(B(3, 4)\)។ តម្លៃ \(x\) គឺ៖', NULL, '["\\(1.5\\)", "\\(2.5\\)", "\\(3\\)", "\\(2\\)"]', 1, NULL, 2, 'mcq', '\(MA^2 = MB^2 \implies (x+1)^2 + 4 = (x-3)^2 + 16 \implies 2x + 5 = -6x + 25 \implies 8x = 20 \implies x = 2.5\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11016, 'បើ \(M(1, 2), N(3, 4), P(5, 0)\) ជាចំណុចកណ្ដាលនៃជ្រុងទាំងបីនៃត្រីកោណ \(ABC\) នោះទីប្រជុំទម្ងន់នៃត្រីកោណ \(ABC\) គឺ៖', NULL, '["\\((4, 2)\\)", "\\((2, 2)\\)", "\\((3, 2)\\)", "\\((3, 3)\\)"]', 2, NULL, 2, 'mcq', 'ទីប្រជុំទម្ងន់នៃត្រីកោណ ABC ត្រួតស៊ីគ្នាជាមួយទីប្រជុំទម្ងន់នៃត្រីកោណ MNP ៖ \(G\left(\dfrac{1+3+5}{3}, \dfrac{2+4+0}{3}\right) = (3, 2)\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11017, 'រកចំណុច \(Q\) ចែកអង្កត់ \(AB\) ខាងក្រៅតាមផលធៀប \(2 : 1\) ដោយ \(A(1, 3)\) និង \(B(4, 5)\)៖', NULL, '["\\((6, 8)\\)", "\\((8, 9)\\)", "\\((5, 6)\\)", "\\((7, 7)\\)"]', 3, NULL, 2, 'mcq', '\(x = \dfrac{2(4) - 1(1)}{2 - 1} = 7, \quad y = \dfrac{2(5) - 1(3)}{2 - 1} = 7\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11018, 'គណនាផ្ទៃក្រឡាចតុកោណ \(ABCD\) ដែលមានកំពូល \(A(1, 1), B(5, 1), C(5, 4), D(1, 4)\)៖', NULL, '["\\(12\\)", "\\(15\\)", "\\(16\\)", "\\(10\\)"]', 0, NULL, 2, 'mcq', 'នេះជាចតុកោណកែងដែលមានបណ្តោយ \(AB = 4\) និងទទឹង \(BC = 3\) ដូច្នេះ \(S = 4 	imes 3 = 12\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11019, 'បើបីចំណុច \(A(0, 0), B(a, 2), C(3, 6)\) រត់ត្រង់ជួរគ្នា នោះតម្លៃ \(a\) គឺ៖', NULL, '["\\(2\\)", "\\(0.5\\)", "\\(3\\)", "\\(1\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{2 - 0}{a - 0} = \dfrac{6 - 0}{3 - 0} = 2 \implies \dfrac{2}{a} = 2 \implies a = 1\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11020, 'ត្រីកោណ \(ABC\) មានកំពូល \(A(0, 5), B(-3, 1), C(3, 1)\)។ ត្រីកោណនេះជាត្រីកោណអ្វី?', NULL, '["ត្រីកោណសម័ង្ស", "ត្រីកោណសមបាត", "ត្រីកោណកែងសមបាត", "ត្រីកោណកែងមិនសមបាត"]', 1, NULL, 2, 'mcq', '\(AB = \sqrt{(-3-0)^2 + (1-5)^2} = 5\) និង \(AC = \sqrt{(3-0)^2 + (1-5)^2} = 5\)។ ដោយ \(AB = AC = 5 
eq BC = 6\) នាំឱ្យជាត្រីកោណសមបាត។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11021, 'ចំណុច \(C\) ស្ថិតនៅលើអង្កត់ \(AB\) ដោយ \(A(1, 2), B(7, 8)\) ហើយ \(AC = \dfrac{1}{3}AB\)។ កូអរដោនេនៃ \(C\) គឺ៖', NULL, '["\\((3, 4)\\)", "\\((2, 3)\\)", "\\((4, 5)\\)", "\\((3, 5)\\)"]', 0, NULL, 2, 'mcq', '\(AC : CB = 1 : 2 \implies x_C = \dfrac{1(7) + 2(1)}{3} = 3, \quad y_C = \dfrac{1(8) + 2(2)}{3} = 4\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11022, 'គណនាផ្ទៃក្រឡាត្រីកោណដែលមានកំពូល \(A(0, 0), B(4, 0), C(0, 3)\)៖', NULL, '["\\(12\\)", "\\(5\\)", "\\(7\\)", "\\(6\\)"]', 3, NULL, 2, 'mcq', '\(S = \dfrac{1}{2}|4(3) - 0(0)| = 6\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11023, 'ត្រីកោណ \(ABC\) មាន \(A(1, 1), B(4, 5), C(13, -8)\)។ ប្រភេទនៃត្រីកោណ \(ABC\) គឺ៖', NULL, '["ត្រីកោណកែងត្រង់ C", "ត្រីកោណកែងត្រង់ A", "ត្រីកោណសម័ង្ស", "ត្រីកោណកែងត្រង់ B"]', 1, NULL, 2, 'mcq', '\(AB^2 = 3^2 + 4^2 = 25\), \(BC^2 = 9^2 + (-13)^2 = 81 + 169 = 250\), \(AC^2 = 12^2 + (-9)^2 = 144 + 81 = 225\)។ ឃើញថា \(AB^2 + AC^2 = 25 + 225 = 250 = BC^2\) ដូច្នេះកែងត្រង់ A។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11024, 'រកកាំ \(R\) នៃរង្វង់ដែលមានអង្កត់ផ្ចិត \(AB\) ដោយ \(A(-3, 2)\) និង \(B(5, -4)\)៖', NULL, '["\\(\\sqrt{50}\\)", "\\(2.5\\)", "\\(5\\)", "\\(10\\)"]', 2, NULL, 2, 'mcq', '\(AB = \sqrt{(5 - (-3))^2 + (-4 - 2)^2} = \sqrt{8^2 + (-6)^2} = \sqrt{64 + 36} = 10 \implies R = \dfrac{AB}{2} = 5\)។', 'កូអរដោនេនៃចំណុច', 'medium', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11025, 'រកកូអរដោនេនៃចំណុច \(P\) នៅលើបន្ទាត់ \(y = 2x\) ដែលមានចម្ងាយស្មើគ្នាពីចំណុច \(A(1, 1)\) និង \(B(5, 3)\)៖', NULL, '["\\((1.5, 3)\\)", "\\((3, 6)\\)", "\\((2, 4)\\)", "\\((1, 2)\\)"]', 2, NULL, 3, 'mcq', 'តាង \(P(x, 2x)\)។ \(PA^2 = PB^2 \implies (x-1)^2 + (2x-1)^2 = (x-5)^2 + (2x-3)^2 \implies 5x^2 - 6x + 2 = 5x^2 - 22x + 34 \implies 16x = 32 \implies x = 2 \implies P(2, 4)\)។', 'កូអរដោនេនៃចំណុច', 'hard', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11026, 'ចតុកោណ \(ABCD\) មានកំពូលតាមលំដាប់ \(A(1, 2), B(5, 3), C(4, 6), D(0, 4)\)។ ផ្ទៃក្រឡានៃចតុកោណនេះគឺ៖', NULL, '["\\(14\\)", "\\(11.5\\)", "\\(12\\)", "\\(23\\)"]', 1, NULL, 3, 'mcq', 'ប្រើរូបមន្ត Shoelace ៖ \(2S = |(1\cdot 3 - 5\cdot 2) + (5\cdot 6 - 4\cdot 3) + (4\cdot 4 - 0\cdot 6) + (0\cdot 2 - 1\cdot 4)| = |-7 + 18 + 16 - 4| = 23 \implies S = 11.5\)។', 'កូអរដោនេនៃចំណុច', 'hard', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11027, 'ចំណុចពីរ \(P\) និង \(Q\) ចែកអង្កត់ \(AB\) ជា 3 ផ្នែកស្មើៗគ្នា (ចំណុចត្រីភាគ) ដោយ \(A(1, 2)\) និង \(B(7, 11)\)។ កូអរដោនេនៃ \(P\) (ជិត A) និង \(Q\) (ជិត B) គឺ៖', NULL, '["\\(P(3, 5), Q(5, 8)\\)", "\\(P(4, 6), Q(5, 7)\\)", "\\(P(3, 6), Q(5, 9)\\)", "\\(P(2, 4), Q(4, 7)\\)"]', 0, NULL, 3, 'mcq', '\(x_P = 1 + \dfrac{6}{3} = 3, y_P = 2 + \dfrac{9}{3} = 5 \implies P(3, 5)\) និង \(x_Q = 3 + 2 = 5, y_Q = 5 + 3 = 8 \implies Q(5, 8)\)។', 'កូអរដោនេនៃចំណុច', 'hard', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11028, 'ចំណុច \(A(1, 5), B(3, 1), C(k, -3)\) រត់ត្រង់ជួរគ្នា។ តម្លៃ \(k\) គឺ៖', NULL, '["\\(4\\)", "\\(6\\)", "\\(5\\)", "\\(4.5\\)"]', 2, NULL, 3, 'mcq', '\(m_{AB} = \dfrac{1-5}{3-1} = -2; \quad m_{BC} = \dfrac{-3-1}{k-3} = \dfrac{-4}{k-3} = -2 \implies k - 3 = 2 \implies k = 5\)។', 'កូអរដោនេនៃចំណុច', 'hard', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11029, 'រកផ្ចិត \(I\) នៃរង្វង់ចារឹកក្រៅត្រីកោណកែងដែលមានកំពូល \(A(0, 0), B(6, 0), C(0, 8)\)៖', NULL, '["\\((3, 4)\\)", "\\((3, 3)\\)", "\\((4, 3)\\)", "\\((2, 3)\\)"]', 0, NULL, 3, 'mcq', 'ត្រីកោណកែងត្រង់ O(0,0) នោះផ្ចិតរង្វង់ចារឹកក្រៅជាចំណុចកណ្ដាលនៃអ៊ីប៉ូតេនុស BC ៖ \(I\left(\dfrac{6+0}{2}, \dfrac{0+8}{2}\right) = (3, 4)\)។', 'កូអរដោនេនៃចំណុច', 'hard', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11030, 'ត្រីកោណមួយមានកំពូល \(A(0, 0), B(4, 2), C(2, k)\) និងមានផ្ទៃក្រឡា \(S = 7\)។ បើ \(k > 0\) នោះតម្លៃ \(k\) គឺ៖', NULL, '["\\(4\\)", "\\(4.5\\)", "\\(5\\)", "\\(3.5\\)"]', 1, NULL, 3, 'mcq', '\(S = \dfrac{1}{2}|4k - 2(2)| = 7 \implies |4k - 4| = 14 \implies 4k - 4 = 14 \implies 4k = 18 \implies k = 4.5\)។', 'កូអរដោនេនៃចំណុច', 'hard', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11031, 'រកប្រវែងមេដ្យាន \(AM\) នៃត្រីកោណ \(ABC\) ដែលមាន \(A(3, 8), B(2, -1), C(4, 3)\)៖', NULL, '["\\(\\sqrt{45}\\)", "\\(\\sqrt{53}\\)", "\\(7\\)", "\\(8\\)"]', 2, NULL, 3, 'mcq', '\(M\left(\dfrac{2+4}{2}, \dfrac{-1+3}{2}\right) = (3, 1) \implies AM = \sqrt{(3-3)^2 + (8-1)^2} = \sqrt{7^2} = 7\)។', 'កូអរដោនេនៃចំណុច', 'hard', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11032, 'ក្នុងប្រព័ន្ធផែនទីឌីជីថល (GPS) ទីតាំងសាលារៀនស្ថិតនៅ \(S(2, 3)\) និងមន្ទីរពេទ្យស្ថិតនៅ \(H(8, 11)\) (គិតជាគីឡូម៉ែត្រ)។ យន្តហោះដ្រូនដឹកថ្នាំពេទ្យហោះជាខ្សែបន្ទាត់ត្រង់ពី S ទៅ H។ ចម្ងាយផ្លូវហោះហើរគឺ៖', NULL, '["\\(8\\text{ km}\\)", "\\(14\\text{ km}\\)", "\\(12\\text{ km}\\)", "\\(10\\text{ km}\\)"]', 3, NULL, 3, 'mcq', '\(d = \sqrt{(8-2)^2 + (11-3)^2} = \sqrt{6^2 + 8^2} = \sqrt{36+64} = 10\text{ km}\)។', 'កូអរដោនេនៃចំណុច', 'pisa', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11033, 'ក្រុមហ៊ុនដឹកជញ្ជូនចង់ដាក់ឃ្លាំងស្តុកទំនិញនៅចំណុចកណ្ដាល \(M\) ចន្លោះរោងចក្រទីមួយ \(F_1(-4, 2)\) និងរោងចក្រទីពីរ \(F_2(6, 8)\)។ កូអរដោនេនៃឃ្លាំងស្តុកទំនិញគឺ៖', NULL, '["\\((2, 5)\\)", "\\((1, 6)\\)", "\\((1, 5)\\)", "\\((5, 3)\\)"]', 2, NULL, 3, 'mcq', '\(M\left(\dfrac{-4+6}{2}, \dfrac{2+8}{2}\right) = (1, 5)\)។', 'កូអរដោនេនៃចំណុច', 'pisa', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11034, 'ភូមិបី \(A(1, 2), B(7, 2), C(4, 8)\) គ្រោងសាងសង់មណ្ឌលសេវាកម្មរួមមួយនៅទីប្រជុំទម្ងន់ \(G\) នៃភូមិទាំងបីដើម្បីឱ្យចម្ងាយជាមធ្យមទៅភូមិនីមួយៗមានតុល្យភាព។ កូអរដោនេនៃមណ្ឌលសេវាកម្មនោះគឺ៖', NULL, '["\\((4, 3.5)\\)", "\\((4, 4)\\)", "\\((3.5, 4)\\)", "\\((4, 5)\\)"]', 1, NULL, 3, 'mcq', '\(G\left(\dfrac{1+7+4}{3}, \dfrac{2+2+8}{3}\right) = \left(\dfrac{12}{3}, \dfrac{12}{3}\right) = (4, 4)\)។', 'កូអរដោនេនៃចំណុច', 'pisa', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11035, 'ដីកសិកម្មមួយកន្លែងមានព្រំប្រទល់កំណត់ដោយត្រីកោណ \(OAB\) លើប្លង់កូអរដោនេ ដោយ \(O(0, 0), A(60, 0), B(30, 40)\) គិតជាម៉ែត្រ។ ផ្ទៃក្រឡានៃដីកសិកម្មនេះស្មើនឹង៖', NULL, '["\\(1\\,500\\text{ m}^2\\)", "\\(2\\,400\\text{ m}^2\\)", "\\(1\\,200\\text{ m}^2\\)", "\\(900\\text{ m}^2\\)"]', 2, NULL, 3, 'mcq', 'បាតដី \(OA = 60\text{ m}\), កម្ពស់ \(h = y_B = 40\text{ m}\) នាំឱ្យ \(S = \dfrac{1}{2} \times 60 \times 40 = 1\,200\text{ m}^2\)។', 'កូអរដោនេនៃចំណុច', 'pisa', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11036, 'ខ្សែបណ្ដាញទឹកស្អាតត្រូវដាក់កាត់តាមចំណុច \(P\) នៅលើបំពង់មេ \(AB\) ដោយ \(A(2, 1)\) និង \(B(11, 7)\) តាមផលធៀប \(AP : PB = 1 : 2\)។ កូអរដោនេនៃចំណុច \(P\) គឺ៖', NULL, '["\\((6, 4)\\)", "\\((5, 4)\\)", "\\((5, 3)\\)", "\\((4, 3)\\)"]', 2, NULL, 3, 'mcq', '\(x_P = \dfrac{1(11) + 2(2)}{1+2} = 5, \quad y_P = \dfrac{1(7) + 2(1)}{1+2} = 3 \implies P(5, 3)\)។', 'កូអរដោនេនៃចំណុច', 'pisa', 1, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11037, 'ក្នុងប្លង់កូអរដោនេ \(Oxy\) គេមានពីរចំណុច \(A(1, 3)\) និង \(B(4, 7)\)។
ក. គណនាប្រវែងអង្កត់ \(AB\)។
ខ. រកកូអរដោនេនៃចំណុចកណ្ដាល \(M\) នៃអង្កត់ \(AB\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តចម្ងាយ d = sqrt((x_B - x_A)^2 + (y_B - y_A)^2) (1 ពិន្ទុ)
ជំនួសតម្លៃគណនា AB = sqrt((4-1)^2 + (7-3)^2) = sqrt(9 + 16) = 5 (1.5 ពិន្ទុ)
សរសេររូបមន្តចំណុចកណ្ដាល x_M = (x_A+x_B)/2, y_M = (y_A+y_B)/2 (1 ពិន្ទុ)
គណនា x_M = (1+4)/2 = 2.5 និង y_M = (3+7)/2 = 5 ដូចនេះ M(2.5, 5) (1.5 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'easy', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11038, 'គេឱ្យពីរចំណុច \(A(-1, 2)\) និង \(B(5, 8)\)។
ក. រកកូអរដោនេនៃចំណុច \(P\) ដែលចែកអង្កត់ \(AB\) ខាងក្នុងតាមផលធៀប \(2 : 1\)។
ខ. រកកូអរដោនេនៃចំណុច \(Q\) ដែលចែកអង្កត់ \(AB\) ខាងក្រៅតាមផលធៀប \(2 : 1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តចែកខាងក្នុង x_P = (m*x_B + n*x_A)/(m+n), y_P = (m*y_B + n*y_A)/(m+n) (1 ពិន្ទុ)
គណនា x_P = (2(5) + 1(-1))/3 = 3, y_P = (2(8) + 1(2))/3 = 6 នាំឱ្យ P(3, 6) (1.5 ពិន្ទុ)
សរសេររូបមន្តចែកខាងក្រៅ x_Q = (m*x_B - n*x_A)/(m-n), y_Q = (m*y_B - n*y_A)/(m-n) (1 ពិន្ទុ)
គណនា x_Q = (2(5) - (-1))/(2-1) = 11, y_Q = (2(8) - 2)/(2-1) = 14 នាំឱ្យ Q(11, 14) (1.5 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'medium', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11039, 'គេមានបីចំណុច \(A(1, 2), B(5, 4), C(3, 8)\) ក្នុងប្លង់កូអរដោនេ។
ក. រកកូអរដោនេកំពូល \(D(x, y)\) ដើម្បីឱ្យចតុកោណ \(ABCD\) ជាប្រលេឡូក្រាម។
ខ. រកកូអរដោនេនៃផ្ចិត \(I\) នៃប្រលេឡូក្រាមនោះ (ចំណុចប្រសព្វនៃអង្កត់ទ្រូង)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់លក្ខខណ្ឌប្រលេឡូក្រាម៖ អង្កត់ទ្រូង AC និង BD កាត់គ្នាត្រង់ចំណុចកណ្ដាល I ដូចគ្នា (1 ពិន្ទុ)
គណនាចំណុចកណ្ដាល I នៃ AC៖ x_I = (1+3)/2 = 2, y_I = (2+8)/2 = 5 នាំឱ្យ I(2, 5) (1.5 ពិន្ទុ)
ទាញរកកូអរដោនេ D តាមទំនាក់ទំនង B + D = 2I នាំឱ្យ x_D = 2x_I - x_B = 4 - 5 = -1 (1.5 ពិន្ទុ)
គណនា y_D = 2y_I - y_B = 10 - 4 = 6 ដូចនេះ D(-1, 6) (1 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'medium', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11040, 'គេឱ្យត្រីកោណ \(ABC\) ដែលមានកំពូល \(A(2, 1), B(6, 4), C(2, 7)\)។
ក. គណនាប្រវែងជ្រុងទាំងបីនៃត្រីកោណ \(ABC\)។
ខ. បង្ហាញថា \(ABC\) ជាត្រីកោណសមបាត រួចគណនាផ្ទៃក្រឡារបស់វា។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា AC = |7 - 1| = 6 (ជ្រុងឈរបញ្ឈរ) (1 ពិន្ទុ)
គណនា AB = sqrt((6-2)^2 + (4-1)^2) = sqrt(16 + 9) = 5 (1 ពិន្ទុ)
គណនា BC = sqrt((6-2)^2 + (4-7)^2) = sqrt(16 + 9) = 5 (1 ពិន្ទុ)
សន្និដ្ឋានថា AB = BC = 5 នាំឱ្យ ABC ជាត្រីកោណសមបាតត្រង់ B (1 ពិន្ទុ)
គណនាកម្ពស់ h ពី B មក AC: h = 6 - 2 = 4 នាំឱ្យ S = (1/2) * 6 * 4 = 12 ឯកតាផ្ទៃ (1 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'medium', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11041, 'គេឱ្យបីចំណុច \(A(-2, 3), B(1, -1), C(4, k)\) ក្នុងប្លង់កូអរដោនេ។
ក. គណនាមេគុណប្រាប់ទិស \(m_{AB}\) នៃបន្ទាត់កាត់តាម \(A\) និង \(B\)។
ខ. រកតម្លៃ \(k\) ដើម្បីឱ្យបីចំណុច \(A, B, C\) រត់ត្រង់ជួរគ្នា។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តមេគុណប្រាប់ទិស m_{AB} = (y_B - y_A)/(x_B - x_A) (1 ពិន្ទុ)
ជំនួសតម្លៃគណនា m_{AB} = (-1 - 3)/(1 - (-2)) = -4/3 (1.5 ពិន្ទុ)
សរសេរលក្ខខណ្ឌត្រង់ជួរគ្នា m_{BC} = m_{AB} នាំឱ្យ (k - (-1))/(4 - 1) = -4/3 (1 ពិន្ទុ)
ដោះស្រាយសមីការ (k+1)/3 = -4/3 នាំឱ្យ k + 1 = -4 នាំឱ្យ k = -5 (1.5 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'medium', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11042, 'គេឱ្យត្រីកោណ \(ABC\) ដែលមានកំពូល \(A(1, 2), B(5, 5), C(2, 6)\)។
ក. គណនាផ្ទៃក្រឡាត្រីកោណ \(ABC\) ដោយប្រើរូបមន្ត Shoelace។
ខ. គណនាប្រវែងជ្រុង \(AB\) រួចទាញរកប្រវែងកម្ពស់ \(h_C\) គូសចេញពីកំពូល \(C\) មកជ្រុង \(AB\)។', NULL, '[]', 0, NULL, 5, 'writing', 'អនុវត្តរូបមន្ត Shoelace: 2S = |1(5-6) + 5(6-2) + 2(2-5)| (1 ពិន្ទុ)
គណនា 2S = |-1 + 20 - 6| = 13 នាំឱ្យផ្ទៃក្រឡា S = 13/2 = 6.5 ឯកតាផ្ទៃ (1.5 ពិន្ទុ)
គណនាប្រវែងជ្រុង AB = sqrt((5-1)^2 + (5-2)^2) = sqrt(16+9) = 5 (1 ពិន្ទុ)
ប្រើរូបមន្តផ្ទៃក្រឡា S = (1/2) * AB * h_C នាំឱ្យ 6.5 = (1/2) * 5 * h_C (0.5 ពិន្ទុ)
ទាញបានប្រវែងកម្ពស់ h_C = (2 * 6.5)/5 = 13/5 = 2.6 (1 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'hard', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11043, 'រកកូអរដោនេនៃចំណុច \(M\) ស្ថិតនៅលើអ័ក្សអាប់ស៊ីស \((x\text{-axis})\) ដែលនៅស្មើចម្ងាយពីចំណុច \(A(2, 3)\) និង \(B(6, 1)\)។
ក. កំណត់ទម្រង់កូអរដោនេនៃចំណុច \(M\)។
ខ. រៀបចំសមីការចម្ងាយ \(MA^2 = MB^2\) រួចដោះស្រាយរក \(x\)។
គ. គណនាចម្ងាយ \(MA\) នោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ទម្រង់ M នៅលើអ័ក្សអាប់ស៊ីស នាំឱ្យ M(x, 0) (1 ពិន្ទុ)
សរសេរកន្សោម MA^2 = (x-2)^2 + (0-3)^2 និង MB^2 = (x-6)^2 + (0-1)^2 (1 ពិន្ទុ)
ពន្លាតសមីការ x^2 - 4x + 13 = x^2 - 12x + 37 នាំឱ្យ 8x = 24 នាំឱ្យ x = 3 ដូចនេះ M(3, 0) (1.5 ពិន្ទុ)
គណនាចម្ងាយ MA = sqrt((3-2)^2 + (0-3)^2) = sqrt(1 + 9) = sqrt(10) (1.5 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'hard', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11044, 'ត្រីកោណ \(ABC\) មានកំពូល \(A(-1, 4), B(3, -2)\) និងទីប្រជុំទម្ងន់ \(G(1, 1)\)។
ក. រកកូអរដោនេនៃកំពូលទីបី \(C\)។
ខ. រកកូអរដោនេនៃចំណុចកណ្ដាល \(M\) នៃជ្រុង \(BC\)។
គ. ផ្ទៀងផ្ទាត់ទំនាក់ទំនងវ៉ិចទ័រ ឬផលធៀប \(AG = \dfrac{2}{3}AM\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រើរូបមន្តទីប្រជុំទម្ងន់ x_G = (x_A+x_B+x_C)/3 នាំឱ្យ x_C = 3(1) - (-1) - 3 = 1 (1 ពិន្ទុ)
គណនា y_C = 3(1) - 4 - (-2) = 1 ដូចនេះ C(1, 1) (1 ពិន្ទុ)
គណនាចំណុចកណ្ដាល M នៃ BC: x_M = (3+1)/2 = 2, y_M = (-2+1)/2 = -0.5 នាំឱ្យ M(2, -0.5) (1 ពិន្ទុ)
គណនាប្រវែង AG = sqrt((1 - (-1))^2 + (1-4)^2) = sqrt(4 + 9) = sqrt(13) (1 ពិន្ទុ)
គណនា AM = sqrt((2 - (-1))^2 + (-0.5 - 4)^2) = sqrt(9 + 20.25) = sqrt(29.25) = 1.5*sqrt(13) នាំឱ្យ AG = (2/3)AM ពិត (1 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'hard', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11045, 'គេឱ្យអង្កត់ \(AB\) ដែលមាន \(A(2, -3)\) និង \(B(8, 9)\)។
ក. រកកូអរដោនេនៃចំណុចប្រសព្វ \(I\) រវាងអង្កត់ \(AB\) និងអ័ក្សអាប់ស៊ីស \((Ox)\)។
ខ. កំណត់ផលធៀបដែល \(I\) ចែកអង្កត់ \(AB\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ចំណុច I ស្ថិតលើ Ox នាំឱ្យ y_I = 0 (1 ពិន្ទុ)
តាងផលធៀប AI : IB = k នាំឱ្យ y_I = (k*y_B + y_A)/(k+1) = 0 (1 ពិន្ទុ)
ជំនួសតម្លៃ (9k - 3)/(k+1) = 0 នាំឱ្យ 9k = 3 នាំឱ្យ k = 1/3 (ផលធៀប 1 : 3) (1.5 ពិន្ទុ)
គណនា x_I = ( (1/3)*8 + 2 ) / (1/3 + 1) = (14/3) / (4/3) = 14/4 = 3.5 ដូចនេះ I(3.5, 0) (1.5 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'hard', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11046, 'ក្នុងគម្រោងរៀបចំប្លង់ក្រុងថ្មី វិស្វករបានកំណត់ប្រព័ន្ធកូអរដោនេលើផ្ទៃដី (គិតជាគីឡូម៉ែត្រ)។
ស្ថានីយ៍រថភ្លើងស្ថិតនៅ \(S(1, 2)\), មន្ទីរពេទ្យស្ថិតនៅ \(H(7, 10)\) ហើយសាលាក្រុងស្ថិតនៅចំណុចកណ្ដាល \(M\) នៃផ្លូវតភ្ជាប់ពីស្ថានីយ៍រថភ្លើងទៅមន្ទីរពេទ្យ។
ក. កំណត់កូអរដោនេនៃសាលាក្រុង \(M\)។
ខ. គណនាប្រវែងផ្លូវត្រង់ពីស្ថានីយ៍រថភ្លើងទៅមន្ទីរពេទ្យ។
គ. បើឡានក្រុងរត់លើផ្លូវត្រង់នេះដោយល្បឿនថេរ \(40\text{ km/h}\) តើត្រូវចំណាយពេលប៉ុន្មាននាទីពី S ទៅ H?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកូអរដោនេសាលាក្រុង M: x_M = (1+7)/2 = 4, y_M = (2+10)/2 = 6 នាំឱ្យ M(4, 6) (1.5 ពិន្ទុ)
គណនាប្រវែងផ្លូវ SH = sqrt((7-1)^2 + (10-2)^2) = sqrt(36 + 64) = 10 km (1.5 ពិន្ទុ)
គណនារយៈពេលធ្វើដំណើរ t = d/v = 10 / 40 = 0.25 ម៉ោង (1 ពិន្ទុ)
បំប្លែងទៅជានាទី៖ 0.25 * 60 = 15 នាទី (1 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'pisa', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11047, 'កសិករម្នាក់មានដីស្រែរាងត្រីកោណ \(ABC\) ដែលមានបង្គោលព្រំប្រទល់កំណត់ដោយកូអរដោនេ \(A(10, 20), B(70, 20), C(40, 60)\) (គិតជាម៉ែត្រ)។
ក. គណនាប្រវែងព្រំប្រទល់ \(AB\) នៃដីស្រែ។
ខ. គណនាផ្ទៃក្រឡាសរុបនៃដីស្រែនេះគិតជាម៉ែត្រការេ \((\text{m}^2)\)។
គ. គាត់ចង់ជីកស្រះស្តុកទឹកតូចមួយនៅត្រង់ទីប្រជុំទម្ងន់ \(G\) នៃដីស្រែ។ ចូររកកូអរដោនេនៃស្រះទឹកនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាប្រវែង AB = |70 - 10| = 60 ម៉ែត្រ (ព្រោះ y_A = y_B = 20) (1 ពិន្ទុ)
កំណត់កម្ពស់ត្រីកោណធៀបនឹងបាត AB: h = 60 - 20 = 40 ម៉ែត្រ (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡាដីស្រែ S = (1/2) * 60 * 40 = 1,200 ម៉ែត្រការេ (1.5 ពិន្ទុ)
គណនាកូអរដោនេទីប្រជុំទម្ងន់ G: x_G = (10+70+40)/3 = 40, y_G = (20+20+60)/3 = 33.33 នាំឱ្យ G(40, 33.33) (1.5 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'pisa', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11048, 'ក្រុមហ៊ុនបណ្ដាញទូរស័ព្ទចល័តមួយ ចង់ដំឡើងបង្គោលអង់តែន \(T\) មួយនៅលើផ្លូវជាតិ \(y = 0\) (អ័ក្សអាប់ស៊ីស) ដើម្បីឱ្យចម្ងាយពីបង្គោលអង់តែននោះទៅភូមិ \(A(1, 3)\) និងភូមិ \(B(7, 5)\) មានប្រវែងស្មើគ្នា (គិតជាគីឡូម៉ែត្រ)។
ក. សរសេរសមីការពិជគណិតដែលត្រូវដោះស្រាយដើម្បីកំណត់ទីតាំងបង្គោលអង់តែន \(T(x, 0)\)។
ខ. រកកូអរដោនេនៃបង្គោលអង់តែន \(T\)។
គ. គណនាចម្ងាយពីបង្គោលអង់តែន \(T\) ទៅភូមិនីមួយៗ។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរសមីការ TA^2 = TB^2 នាំឱ្យ (x-1)^2 + 3^2 = (x-7)^2 + 5^2 (1 ពិន្ទុ)
ពន្លាត x^2 - 2x + 1 + 9 = x^2 - 14x + 49 + 25 នាំឱ្យ -2x + 10 = -14x + 74 (1.5 ពិន្ទុ)
ដោះស្រាយសមីការ 12x = 64 នាំឱ្យ x = 64/12 = 16/3 = 5.33 km នាំឱ្យ T(16/3, 0) (1.5 ពិន្ទុ)
គណនាចម្ងាយ TA = sqrt((16/3 - 1)^2 + 9) = sqrt((13/3)^2 + 9) = sqrt(169/9 + 81/9) = sqrt(250)/3 ≈ 5.27 km (1 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'pisa', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11049, 'ក្រុមហ៊ុនចែកចាញទំនិញដឹកជញ្ជូនរវាងឃ្លាំង \(A(0, 0)\) និងអតិថិជនធំ \(B(12, 9)\) (គិតជាគីឡូម៉ែត្រ)។ គេចង់ដាក់ចំណតផ្ទេរទំនិញ \(P\) នៅលើផ្លូវត្រង់ \(AB\) ដោយចម្ងាយពី \(A\) ទៅ \(P\) ស្មើពីរដងនៃចម្ងាយពី \(P\) ទៅ \(B\)។
ក. កំណត់ផលធៀប \(AP : PB\)។
ខ. រកកូអរដោនេនៃចំណតផ្ទេរទំនិញ \(P\)។
គ. គណនាចម្ងាយសរុប \(AB\) និងចម្ងាយ \(AP\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ផលធៀបចែកខាងក្នុង AP : PB = 2 : 1 (ព្រោះ AP = 2PB) (1 ពិន្ទុ)
អនុវត្តរូបមន្តចែកអង្កត់ x_P = (2(12) + 1(0))/3 = 8, y_P = (2(9) + 1(0))/3 = 6 នាំឱ្យ P(8, 6) (1.5 ពិន្ទុ)
គណនាប្រវែងផ្លូវសរុប AB = sqrt(12^2 + 9^2) = sqrt(144 + 81) = 15 km (1.5 ពិន្ទុ)
គណនាចម្ងាយ AP = (2/3) * 15 = 10 km (1 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'pisa', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11050, 'ក្បាលដីឡូត៍មួយមានរាងជាចតុកោណកែង \(ABCD\) លើប្លង់វាស់វែងដីធ្លី ដែលមានកំពូល \(A(2, 1), B(8, 1), C(8, 5), D(2, 5)\) (ឯកតាគិតជាដប់ម៉ែត្រ៖ 1 ឯកតា = 10m)។
ក. គណនាវិមាត្របណ្តោយ និងទទឹងនៃដីឡូត៍គិតជាម៉ែត្រ។
ខ. គណនាផ្ទៃក្រឡានិងបរិមាត្រពិតប្រាកដនៃដីឡូត៍។
គ. បើគេលក់ដីនេះក្នុងតម្លៃ \(150\text{ ដុល្លារ/m}^2\) តើដីឡូត៍នេះមានតម្លៃសរុបប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាបណ្តោយ AB = 8 - 2 = 6 ឯកតា = 60 ម៉ែត្រ (1 ពិន្ទុ)
គណនាទទឹង AD = 5 - 1 = 4 ឯកតា = 40 ម៉ែត្រ (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡាពិត S = 60 * 40 = 2,400 ម៉ែត្រការេ (1 ពិន្ទុ)
គណនាបរិមាត្រពិត P = 2(60 + 40) = 200 ម៉ែត្រ (1 ពិន្ទុ)
គណនាតម្លៃដីសរុប 2,400 * 150 = 360,000 ដុល្លារ (1 ពិន្ទុ)', 'កូអរដោនេនៃចំណុច', 'pisa', 0, '10', 'កូអរដោនេនៃចំណុច', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
