INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11101, 'តាមរូបភាព គណនាមេគុណប្រាប់ទិស \(m\) នៃបន្ទាត់ដែលកាត់តាម \(A(0, 1)\) និង \(B(4, 4)\)៖', 'g10-b776c350ed.svg', '["\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{3}{4}\\)", "\\(1\\)", "\\(\\dfrac{4}{3}\\)"]', 1, NULL, 1, 'mcq', '\(m = \dfrac{y_B - y_A}{x_B - x_A} = \dfrac{4 - 1}{4 - 0} = \dfrac{3}{4}\)។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11102, 'សមីការបន្ទាត់ដែលមានមេគុណប្រាប់ទិស \(m = 3\) និងកាត់តាមចំណុច \(P(0, -2)\) គឺ៖', NULL, '["\\(y = -2x + 3\\)", "\\(y = 3x + 2\\)", "\\(3x + y = 2\\)", "\\(y = 3x - 2\\)"]', 3, NULL, 1, 'mcq', 'ទម្រង់ \(y = mx + b\) ដោយ \(m = 3, b = -2\) នាំឱ្យ \(y = 3x - 2\)។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
