INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11103, 'តាមរូបភាព ដើម្បីឱ្យបន្ទាត់ពីរ \(d_1\) និង \(d_2\) ស្របគ្នា លក្ខខណ្ឌនៃមេគុណប្រាប់ទិសរបស់វាគឺ៖', 'g10-d0a482fd21.svg', '["\\(m_1 \\cdot m_2 = -1\\)", "\\(m_1 \\cdot m_2 = 1\\)", "\\(m_1 + m_2 = 0\\)", "\\(m_1 = m_2\\)"]', 3, NULL, 1, 'mcq', 'បន្ទាត់ពីរស្របគ្នាកាលណាមេគុណប្រាប់ទិសស្មើគ្នា \(m_1 = m_2\)។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
