INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11104, 'រូបមន្តចម្ងាយពីចំណុច \(M(x_0, y_0)\) ទៅបន្ទាត់ \(\Delta: ax + by + c = 0\) គឺ៖', 'g10-5fe602ea7d.svg', '["\\(d = \\dfrac{|ax_0 + by_0 + c|}{\\sqrt{a^2 + b^2}}\\)", "\\(d = \\sqrt{(x_0 - a)^2 + (y_0 - b)^2}\\)", "\\(d = \\dfrac{|ax_0 + by_0 + c|}{a^2 + b^2}\\)", "\\(d = \\dfrac{ax_0 + by_0 + c}{\\sqrt{a^2 + b^2}}\\)"]', 0, NULL, 1, 'mcq', 'នេះជារូបមន្តគណនាចម្ងាយពីចំណុចទៅបន្ទាត់ក្នុងប្លង់។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11105, 'កូអរដោនេនៃចំណុចប្រសព្វរវាងបន្ទាត់ \(y = 2x + 1\) និងអ័ក្សអ័រដោនេ \((Oy)\) គឺ៖', NULL, '["\\((0, 2)\\)", "\\((0, 1)\\)", "\\((1, 0)\\)", "\\((-0.5, 0)\\)"]', 1, NULL, 1, 'mcq', 'ឱ្យ \(x = 0 \implies y = 2(0) + 1 = 1 \implies (0, 1)\)។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11106, 'មេគុណប្រាប់ទិស \(m\) នៃបន្ទាត់ដេក (ស្របនឹងអ័ក្សអាប់ស៊ីស) មានតម្លៃស្មើនឹង៖', NULL, '["\\(1\\)", "\\(0\\)", "\\(-1\\)", "មិនកំណត់ (គ្មាននិយមន័យ)"]', 1, NULL, 1, 'mcq', 'បន្ទាត់ដេកមាន \(\Delta y = 0\) ដូច្នេះមេគុណប្រាប់ទិស \(m = 0\)។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11107, 'សមីការទូទៅនៃបន្ទាត់ \(2x - 3y + 6 = 0\) មានមេគុណប្រាប់ទិស \(m\) ស្មើនឹង៖', NULL, '["\\(-\\dfrac{2}{3}\\)", "\\(2\\)", "\\(\\dfrac{3}{2}\\)", "\\(\\dfrac{2}{3}\\)"]', 3, NULL, 1, 'mcq', 'បំប្លែង \(3y = 2x + 6 \implies y = \dfrac{2}{3}x + 2 \implies m = \dfrac{2}{3}\)។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
