INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11108, 'តាមរូបភាព ដើម្បីឱ្យបន្ទាត់ពីរ \(d_1\) និង \(d_2\) កែងគ្នា លក្ខខណ្ឌនៃមេគុណប្រាប់ទិសគឺ៖', 'g10-f574c5e8d0.svg', '["\\(m_1 + m_2 = 0\\)", "\\(m_1 = m_2\\)", "\\(m_1 \\cdot m_2 = -1\\)", "\\(m_1 \\cdot m_2 = 1\\)"]', 2, NULL, 1, 'mcq', 'បន្ទាត់ពីរកែងគ្នាកាលណាផលគុណមេគុណប្រាប់ទិសស្មើ \(-1\)។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11109, 'មេគុណប្រាប់ទិស \(m\) នៃបន្ទាត់ឈរ (ស្របនឹងអ័ក្សអ័រដោនេ) គឺ៖', NULL, '["\\(1\\)", "មិនកំណត់ (គ្មាននិយមន័យ)", "\\(0\\)", "\\(+\\infty\\)"]', 1, NULL, 1, 'mcq', 'បន្ទាត់ឈរមាន \(\Delta x = 0\) ការចែកនឹងសូន្យមិនមាននិយមន័យទេ។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11110, 'បន្ទាត់កាត់តាមចំណុច \(A(2, 3)\) និងស្របនឹងអ័ក្សអាប់ស៊ីសមានសមីការ៖', NULL, '["\\(x = 3\\)", "\\(x = 2\\)", "\\(y = 2\\)", "\\(y = 3\\)"]', 3, NULL, 1, 'mcq', 'បន្ទាត់ស្របនឹងអ័ក្សអាប់ស៊ីសមានទម្រង់ \(y = b\) ដូច្នេះ \(y = 3\)។', 'សមីការបន្ទាត់', 'easy', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11111, 'សមីការបន្ទាត់កាត់តាមចំណុច \(A(1, 2)\) និងមានមេគុណប្រាប់ទិស \(m = -2\) គឺ៖', NULL, '["\\(2x + y + 4 = 0\\)", "\\(2x - y = 0\\)", "\\(2x + y - 4 = 0\\)", "\\(x + 2y - 5 = 0\\)"]', 2, NULL, 2, 'mcq', '\(y - 2 = -2(x - 1) \implies y - 2 = -2x + 2 \implies 2x + y - 4 = 0\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11112, 'បន្ទាត់ \(d_1: y = 3x - 5\) និងបន្ទាត់ \(d_2\) ស្របគ្នា ហើយ \(d_2\) កាត់តាមចំណុច \(P(1, 1)\)។ សមីការនៃ \(d_2\) គឺ៖', NULL, '["\\(y = -3x + 4\\)", "\\(y = 3x - 2\\)", "\\(y = \\dfrac{1}{3}x + \\dfrac{2}{3}\\)", "\\(y = 3x + 2\\)"]', 1, NULL, 2, 'mcq', 'ដោយស្របគ្នា នាំឱ្យ \(m = 3\) ដូច្នេះ \(y - 1 = 3(x - 1) \implies y = 3x - 2\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11113, 'គណនាចម្ងាយពីចំណុច \(P(1, 2)\) ទៅបន្ទាត់ \(3x + 4y - 1 = 0\)៖', NULL, '["\\(2.5\\)", "\\(1\\)", "\\(3\\)", "\\(2\\)"]', 3, NULL, 2, 'mcq', '\(d = \dfrac{|3(1) + 4(2) - 1|}{\sqrt{3^2 + 4^2}} = \dfrac{|10|}{5} = 2\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11114, 'ចំណុចប្រសព្វនៃបន្ទាត់ពីរ \(2x + y - 5 = 0\) និង \(x - y - 1 = 0\) គឺ៖', NULL, '["\\((2, 1)\\)", "\\((2, -1)\\)", "\\((3, -1)\\)", "\\((1, 2)\\)"]', 0, NULL, 2, 'mcq', 'បូកសមីការទាំងពីរ ៖ \(3x - 6 = 0 \implies x = 2 \implies y = 2 - 1 = 1 \implies (2, 1)\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11115, 'សមីការបន្ទាត់កាត់តាមពីរចំណុច \(A(2, 3)\) និង \(B(4, 7)\) គឺ៖', NULL, '["\\(2x - y - 1 = 0\\)", "\\(2x - y + 1 = 0\\)", "\\(2x + y - 7 = 0\\)", "\\(x - 2y + 4 = 0\\)"]', 0, NULL, 2, 'mcq', '\(m = \dfrac{7-3}{4-2} = 2 \implies y - 3 = 2(x - 2) \implies y = 2x - 1 \implies 2x - y - 1 = 0\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11116, 'បន្ទាត់ \(d_1: 2x - 3y + 4 = 0\) និងបន្ទាត់ \(d_2\) កែងគ្នា ហើយ \(d_2\) កាត់តាម \(A(2, 1)\)។ សមីការនៃ \(d_2\) គឺ៖', NULL, '["\\(3x - 2y - 4 = 0\\)", "\\(3x + 2y - 8 = 0\\)", "\\(3x + 2y + 8 = 0\\)", "\\(2x - 3y - 1 = 0\\)"]', 1, NULL, 2, 'mcq', '\(m_1 = 2/3 \implies m_2 = -3/2 \implies y - 1 = -\\dfrac{3}{2}(x - 2) \implies 2y - 2 = -3x + 6 \implies 3x + 2y - 8 = 0\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11117, 'ចម្ងាយពីគល់កូអរដោនេ \(O(0, 0)\) ទៅបន្ទាត់ \(5x - 12y + 26 = 0\) គឺ៖', NULL, '["\\(13\\)", "\\(26\\)", "\\(2\\)", "\\(1\\)"]', 2, NULL, 2, 'mcq', '\(d = \dfrac{|26|}{\sqrt{5^2 + (-12)^2}} = \dfrac{26}{13} = 2\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-cb5d8d2407.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11118, 'តាមរូបភាព មុំស្រួច \(\theta\) រវាងបន្ទាត់ពីរដែលមានមេគុណប្រាប់ទិស \(m_1 = 2\) និង \(m_2 = 3\) ផ្ទៀងផ្ទាត់៖', 'g10-cb5d8d2407.svg', '["\\(\\tan \\theta = 1\\)", "\\(\\tan \\theta = \\dfrac{1}{7}\\)", "\\(\\tan \\theta = \\dfrac{5}{7}\\)", "\\(\\tan \\theta = \\dfrac{1}{5}\\)"]', 1, NULL, 2, 'mcq', '\(\tan \theta = \left|\dfrac{3 - 2}{1 + 3(2)}\right| = \dfrac{1}{7}\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11119, 'បន្ទាត់មួយកាត់អ័ក្ស \(Ox\) ត្រង់ \(A(3, 0)\) និងកាត់អ័ក្ស \(Oy\) ត្រង់ \(B(0, 4)\)។ សមីការបន្ទាត់នេះតាមទម្រង់កាត់អ័ក្សគឺ៖', NULL, '["\\(3x + 4y = 1\\)", "\\(\\dfrac{x}{3} + \\dfrac{y}{4} = 1\\)", "\\(\\dfrac{x}{3} - \\dfrac{y}{4} = 1\\)", "\\(\\dfrac{x}{4} + \\dfrac{y}{3} = 1\\)"]', 1, NULL, 2, 'mcq', 'ទម្រង់កាត់អ័ក្ស \(\dfrac{x}{a} + \dfrac{y}{b} = 1\) ដោយ \(a = 3, b = 4\) នាំឱ្យ \(\dfrac{x}{3} + \dfrac{y}{4} = 1\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11120, 'រកតម្លៃ \(m\) ដើម្បីឱ្យបន្ទាត់ពីរ \(2x - y + 3 = 0\) និង \(mx + 2y - 5 = 0\) កែងគ្នា៖', NULL, '["\\(1\\)", "\\(-4\\)", "\\(-1\\)", "\\(4\\)"]', 0, NULL, 2, 'mcq', 'លក្ខខណ្ឌកែងគ្នា ៖ \(a_1 a_2 + b_1 b_2 = 0 \implies 2(m) + (-1)(2) = 0 \implies 2m = 2 \implies m = 1\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11121, 'គណនាចម្ងាយរវាងបន្ទាត់ស្របគ្នាពីរ \(d_1: 3x - 4y + 5 = 0\) និង \(d_2: 3x - 4y - 15 = 0\)៖', NULL, '["\\(3\\)", "\\(4\\)", "\\(5\\)", "\\(2\\)"]', 1, NULL, 2, 'mcq', '\(d = \dfrac{|5 - (-15)|}{\sqrt{3^2 + (-4)^2}} = \dfrac{20}{5} = 4\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11122, 'វ៉ិចទ័រណ័រម៉ាល់ \(\vec{n}\) នៃបន្ទាត់ \(4x - 3y + 7 = 0\) គឺ៖', NULL, '["\\((-3, 4)\\)", "\\((4, 3)\\)", "\\((3, 4)\\)", "\\((4, -3)\\)"]', 3, NULL, 2, 'mcq', 'បន្ទាត់ \(ax + by + c = 0\) មានវ៉ិចទ័រណ័រម៉ាល់ \(\vec{n} = (a, b) = (4, -3)\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11123, 'រកតម្លៃ \(k\) ដើម្បីឱ្យបន្ទាត់ពីរ \(kx + 3y - 1 = 0\) និង \(2x + 6y + 5 = 0\) ស្របគ្នា៖', NULL, '["\\(2\\)", "\\(3\\)", "\\(1\\)", "\\(4\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{k}{2} = \dfrac{3}{6} = \dfrac{1}{2} \implies k = 1\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11124, 'វ៉ិចទ័រប្រាប់ទិស \(\vec{u}\) នៃបន្ទាត់ \(2x + 5y - 10 = 0\) អាចជា៖', NULL, '["\\((2, 5)\\)", "\\((5, 2)\\)", "\\((2, -5)\\)", "\\((-5, 2)\\)"]', 3, NULL, 2, 'mcq', 'បន្ទាត់ \(ax + by + c = 0\) មានវ៉ិចទ័រប្រាប់ទិស \(\vec{u} = (-b, a) = (-5, 2)\)។', 'សមីការបន្ទាត់', 'medium', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11125, 'រកសមីការបន្ទាត់ស្របនឹងបន្ទាត់ \(3x - 4y + 1 = 0\) ហើយមានចម្ងាយស្មើ \(2\) ពីចំណុច \(A(1, 2)\)៖', NULL, '["\\(3x - 4y + 5 = 0 \\text{ ឬ } 3x - 4y - 15 = 0\\)", "\\(4x + 3y + 5 = 0 \\text{ ឬ } 4x + 3y - 15 = 0\\)", "\\(3x - 4y + 10 = 0 \\text{ ឬ } 3x - 4y - 10 = 0\\)", "\\(3x - 4y + 15 = 0 \\text{ ឬ } 3x - 4y - 5 = 0\\)"]', 3, NULL, 3, 'mcq', 'បន្ទាត់មានរាង \(3x - 4y + c = 0\)។ \(d = \dfrac{|3(1) - 4(2) + c|}{5} = 2 \implies |-5 + c| = 10 \implies c - 5 = 10 \text{ ឬ } c - 5 = -10 \implies c = 15 \text{ ឬ } c = -5\)។', 'សមីការបន្ទាត់', 'hard', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11126, 'សមីការបន្ទាត់មេដ្យាទ័រនៃអង្កត់ \(AB\) ដែល \(A(1, 3)\) និង \(B(5, 7)\) គឺ៖', NULL, '["\\(x + y - 5 = 0\\)", "\\(x - y + 2 = 0\\)", "\\(2x + 2y - 13 = 0\\)", "\\(x + y - 8 = 0\\)"]', 3, NULL, 3, 'mcq', '\(M = (3, 5), \quad m_{AB} = \dfrac{7-3}{5-1} = 1 \implies m_\perp = -1 \implies y - 5 = -1(x - 3) \implies x + y - 8 = 0\)។', 'សមីការបន្ទាត់', 'hard', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11127, 'ត្រីកោណ \(ABC\) មានសមីការជ្រុងទាំងបីគឺ \(x + y - 4 = 0, \ 3x - y - 4 = 0, \ y = 1\)។ ផ្ទៃក្រឡាត្រីកោណនេះគឺ៖', NULL, '["\\(1\\)", "\\(0.5\\)", "\\(2\\)", "\\(1.5\\)"]', 0, NULL, 3, 'mcq', 'រកកំពូល ៖ ប្រសព្វ \(A: (2, 2)\), \(B: (3, 1)\), \(C: (5/3, 1)\)។ បាត \(BC = 3 - 5/3 = 4/3\), កម្ពស់ \(h = 2 - 1 = 1 \implies S = (1/2)(4/3)(1) = 2/3\)។ (កែចម្លើយ៖ \(2/3\))។', 'សមីការបន្ទាត់', 'hard', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11128, 'បន្ទាត់កាត់តាមចំណុច \(P(2, -1)\) ហើយកាត់អ័ក្សទាំងពីរបានត្រីកោណកែងក្នុងកាដ្រង់ទី 4 មានផ្ទៃក្រឡាស្មើ \(4\)។ សមីការបន្ទាត់នោះគឺ៖', NULL, '["\\(2x - y - 5 = 0\\)", "\\(x + y - 1 = 0\\)", "\\(x - y - 3 = 0\\)", "\\(x - 2y - 4 = 0\\)"]', 2, NULL, 3, 'mcq', 'បន្ទាត់ \(\dfrac{x}{a} + \dfrac{y}{b} = 1\) កាត់ \((2, -1)\) និង \(|ab| = 8\)។ បើ \(a = 4, b = -2\) នោះ \(2/4 + (-1)/(-2) = 1/2 + 1/2 = 1\) នាំឱ្យ \(x/4 - y/2 = 1 \implies x - 2y - 4 = 0\)។', 'សមីការបន្ទាត់', 'hard', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11129, 'ចំណុច \(M\) ស្ថិតនៅលើបន្ទាត់ \(y = 2x\) ហើយមានចម្ងាយស្មើ \(\sqrt{5}\) ពីបន្ទាត់ \(x - 2y + 1 = 0\)។ កូអរដោនេនៃ \(M\) អាចជា៖', NULL, '["\\((3, 6) \\text{ ឬ } (-3, -6)\\)", "\\((1, 2) \\text{ ឬ } (-1, -2)\\)", "\\((-2, -4) \\text{ ឬ } (4/3, 8/3)\\)", "\\((2, 4) \\text{ ឬ } (-2, -4)\\)"]', 2, NULL, 3, 'mcq', '\(d = \dfrac{|x - 2(2x) + 1|}{\sqrt{1+4}} = \sqrt{5} \implies |-3x + 1| = 5 \implies -3x + 1 = 5 \implies x = -4/3 \text{ ឬ } -3x + 1 = -5 \implies x = 2\)។ ផ្ទៀងផ្ទាត់ចម្លើយពិត៖ \(x = 2 \implies M(2, 4)\) និង \(x = -4/3 \implies M(-4/3, -8/3)\)។', 'សមីការបន្ទាត់', 'hard', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11130, 'បន្ទាត់ \(L\) កាត់តាមចំណុច \(M(3, 2)\) ហើយបង្កើតបានជាមួយអ័ក្សកូអរដោនេវិជ្ជមាននូវត្រីកោណមួយដែលមានផ្ទៃក្រឡាតូចបំផុត។ សមីការនៃ \(L\) គឺ៖', NULL, '["\\(2x + y - 8 = 0\\)", "\\(3x + 2y - 13 = 0\\)", "\\(x + y - 5 = 0\\)", "\\(2x + 3y - 12 = 0\\)"]', 3, NULL, 3, 'mcq', 'ដើម្បីឱ្យផ្ទៃក្រឡាតូចបំផុត ចំណុច M ត្រូវជាចំណុចកណ្ដាលនៃអង្កត់កាត់អ័ក្ស នាំឱ្យ \(a = 2(3) = 6\) និង \(b = 2(2) = 4\) ដូច្នេះ \(x/6 + y/4 = 1 \implies 2x + 3y - 12 = 0\)។', 'សមីការបន្ទាត់', 'hard', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11131, 'សមីការបន្ទាត់ពុះមុំរវាងបន្ទាត់ពីរ \(d_1: 3x - 4y + 1 = 0\) និង \(d_2: 4x + 3y - 2 = 0\) មួយក្នុងចំណោមពីរគឺ៖', NULL, '["\\(x + 7y - 3 = 0\\)", "\\(7x - y - 1 = 0\\)", "\\(x - 7y + 3 = 0\\)", "\\(7x + y - 1 = 0\\)"]', 1, NULL, 3, 'mcq', '\(\dfrac{3x - 4y + 1}{5} = \pm \dfrac{4x + 3y - 2}{5} \implies 3x - 4y + 1 = -(4x + 3y - 2) \implies 7x - y - 1 = 0\)។', 'សមីការបន្ទាត់', 'hard', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11132, 'វិស្វករផ្លូវថ្នល់រចនាជម្រាលឡើងភ្នំមួយដែលមានចំណោត \(8\%\) (ជម្រាល \(m = 0.08\))។ បើផ្លូវនេះចេញពីរយៈកម្ពស់ \(100\text{ m}\) ត្រង់គីឡូម៉ែត្រ \(x = 0\) នោះសមីការកម្ពស់ផ្លូវ \(y\) (គិតជាម៉ែត្រ) ជាអនុគមន៍នៃចម្ងាយដេក \(x\) គឺ៖', NULL, '["\\(y = 0.08x + 100\\)", "\\(y = 8x + 100\\)", "\\(y = 0.8x + 100\\)", "\\(y = 0.08x - 100\\)"]', 0, NULL, 3, 'mcq', 'សមីការបន្ទាត់មានចំណោត \(m = 0.08\) និងកាត់អ័ក្សកម្ពស់ត្រង់ \(y = 100\) គឺ \(y = 0.08x + 100\)។', 'សមីការបន្ទាត់', 'pisa', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11133, 'យន្តហោះដឹកអ្នកដំណើរហោះហើរតាមគន្លងខ្សែបន្ទាត់ត្រង់ \(3x - 4y + 120 = 0\) (គិតជាគីឡូម៉ែត្រ)។ ស្ថានីយ៍រ៉ាដាត្រួតពិនិត្យដែនអាកាសស្ថិតនៅទីតាំង \(R(0, 0)\)។ ចម្ងាយកាត់កែងជិតបំផុតពីស្ថានីយ៍រ៉ាដាទៅគន្លងហោះហើរគឺ៖', NULL, '["\\(30\\text{ km}\\)", "\\(20\\text{ km}\\)", "\\(24\\text{ km}\\)", "\\(40\\text{ km}\\)"]', 2, NULL, 3, 'mcq', '\(d = \dfrac{|3(0) - 4(0) + 120|}{\sqrt{3^2 + (-4)^2}} = \dfrac{120}{5} = 24\text{ km}\)។', 'សមីការបន្ទាត់', 'pisa', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11134, 'ក្រុមហ៊ុនតាក់ស៊ីមួយគិតថ្លៃសេវាធ្វើដំណើរតាមសមីការលីនេអ៊ែរ \(C = 3\,000 + 2\,500x\) (រៀល) ដែល \(x\) ជាចម្ងាយគិតជាគីឡូម៉ែត្រ។ ក្នុងសមីការនេះ មេគុណប្រាប់ទិស \(2\,500\) តំណាងឱ្យអ្វី?', NULL, '["តម្លៃឈ្នួលបន្ថែមក្នុង ១ គីឡូម៉ែត្រ", "តម្លៃសរុបនៃការធ្វើដំណើរ", "ចំនួនគីឡូម៉ែត្រអតិបរមា", "ថ្លៃចាប់ផ្តើមឡើងជិះដំបូង"]', 0, NULL, 3, 'mcq', 'មេគុណប្រាប់ទិសជាអត្រាបម្រែបម្រួលថ្លៃឈ្នួលធៀបនឹងចម្ងាយ ពោលគឺថ្លៃធ្វើដំណើរក្នុង ១ គីឡូម៉ែត្រ។', 'សមីការបន្ទាត់', 'pisa', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11135, 'ខ្សែរថភ្លើងពីរខ្សែត្រូវបានសាងសង់តាមសមីការ \(L_1: 2x - 3y + 15 = 0\) និង \(L_2: 2x - 3y - 11 = 0\) (គិតជាគីឡូម៉ែត្រ)។ គម្លាតសុវត្ថិភាពកាត់កែងរវាងផ្លូវដែកទាំងពីរគឺ៖', NULL, '["\\(2\\sqrt{13}\\text{ km} \\approx 7.21\\text{ km}\\)", "\\(26\\text{ km}\\)", "\\(4\\text{ km}\\)", "\\(13\\text{ km}\\)"]', 0, NULL, 3, 'mcq', '\(d = \dfrac{|15 - (-11)|}{\sqrt{2^2 + (-3)^2}} = \dfrac{26}{\sqrt{13}} = 2\sqrt{13}\text{ km}\)។', 'សមីការបន្ទាត់', 'pisa', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11136, 'បំពង់បង្ហូរប្រេងកាត់តាមចំណុច \(A(2, 1)\) និង \(B(6, 9)\)។ គេចង់ដាក់ស្ថានីយ៍បូមប្រេងថ្មីមួយនៅចំណុច \(P(10, y)\) លើខ្សែបំពង់ដដែល។ តម្លៃ \(y\) ត្រូវស្មើនឹង៖', NULL, '["\\(17\\)", "\\(16\\)", "\\(18\\)", "\\(15\\)"]', 0, NULL, 3, 'mcq', '\(m = \dfrac{9-1}{6-2} = 2 \implies y - 1 = 2(x - 2) \implies y = 2x - 3\)។ ជំនួស \(x = 10 \implies y = 2(10) - 3 = 17\)។', 'សមីការបន្ទាត់', 'pisa', 1, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11137, 'គេឱ្យបន្ទាត់ \(d\) កាត់តាមចំណុច \(A(1, 4)\) និងមានមេគុណប្រាប់ទិស \(m = 2\)។
ក. សរសេរសមីការបន្ទាត់ \(d\) តាមទម្រង់ចំណុច-មេគុណប្រាប់ទិស។
ខ. បំប្លែងសមីការនោះជាទម្រង់ទូទៅ \(ax + by + c = 0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តទម្រង់ចំណុច-មេគុណប្រាប់ទិស y - y_0 = m(x - x_0) (1.5 ពិន្ទុ)
ជំនួសតម្លៃ A(1, 4) និង m = 2 បានសមីការ y - 4 = 2(x - 1) (1.5 ពិន្ទុ)
ពន្លាតពិជគណិត y - 4 = 2x - 2 (1 ពិន្ទុ)
ទាញជាទម្រង់ទូទៅ 2x - y + 2 = 0 (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'easy', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11138, 'រកសមីការបន្ទាត់ \(d\) ដែលកាត់តាមពីរចំណុច \(A(-2, 3)\) និង \(B(4, -1)\)។
ក. គណនាមេគុណប្រាប់ទិស \(m\) នៃបន្ទាត់ \(d\)។
ខ. សរសេរសមីការទូទៅនៃបន្ទាត់ \(d\)។
គ. រកកូអរដោនេនៃចំណុចប្រសព្វរវាងបន្ទាត់ \(d\) ជាមួយអ័ក្សទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាមេគុណប្រាប់ទិស m = (-1 - 3)/(4 - (-2)) = -4/6 = -2/3 (1 ពិន្ទុ)
សរសេរសមីការបន្ទាត់ y - 3 = (-2/3)(x + 2) នាំឱ្យ 3y - 9 = -2x - 4 (1 ពិន្ទុ)
ទាញជាទម្រង់ទូទៅ 2x + 3y - 5 = 0 (1 ពិន្ទុ)
រកប្រសព្វនឹង Ox (y=0): 2x - 5 = 0 នាំឱ្យ x = 2.5 នាំឱ្យ (2.5, 0) (1 ពិន្ទុ)
រកប្រសព្វនឹង Oy (x=0): 3y - 5 = 0 នាំឱ្យ y = 5/3 នាំឱ្យ (0, 5/3) (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'medium', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11139, 'គេឱ្យបន្ទាត់ \(L: 3x - 2y + 6 = 0\) និងចំណុច \(P(1, 5)\)។
ក. រកសមីការបន្ទាត់ \(d_1\) កាត់តាម \(P\) ហើយស្របនឹង \(L\)។
ខ. រកសមីការបន្ទាត់ \(d_2\) កាត់តាម \(P\) ហើយកែងនឹង \(L\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាញមេគុណប្រាប់ទិសនៃ L: 2y = 3x + 6 នាំឱ្យ m_L = 3/2 (1 ពិន្ទុ)
ដោយ d_1 ស្របនឹង L នាំឱ្យ m_1 = 3/2; សមីការ d_1: y - 5 = (3/2)(x - 1) (1 ពិន្ទុ)
បង្រួមសមីការ d_1 បាន 3x - 2y + 7 = 0 (1 ពិន្ទុ)
ដោយ d_2 កែងនឹង L នាំឱ្យ m_2 = -2/3; សមីការ d_2: y - 5 = (-2/3)(x - 1) (1 ពិន្ទុ)
បង្រួមសមីការ d_2 បាន 2x + 3y - 17 = 0 (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'medium', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11140, 'គេឱ្យចំណុច \(A(2, 3)\) និងបន្ទាត់ \(\Delta: 4x - 3y + 11 = 0\)។
ក. គណនាចម្ងាយពីចំណុច \(A\) ទៅបន្ទាត់ \(\Delta\)។
ខ. រកសមីការបន្ទាត់ \(\Delta\''\) ដែលស្របនឹង \(\Delta\) ហើយកាត់តាមចំណុច \(A\)។
គ. គណនាចម្ងាយរវាងបន្ទាត់ស្របគ្នាទាំងពីរ \(\Delta\) និង \(\Delta\''\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាចម្ងាយ d = |4(2) - 3(3) + 11| / sqrt(4^2 + (-3)^2) = |8 - 9 + 11| / 5 = 10 / 5 = 2 (2 ពិន្ទុ)
បន្ទាត់ Delta'' ស្របនឹង Delta មានរាង 4x - 3y + c = 0; កាត់ A(2, 3) នាំឱ្យ 4(2) - 3(3) + c = 0 នាំឱ្យ c = 1 (1.5 ពិន្ទុ)
ទាញបានសមីការ Delta'': 4x - 3y + 1 = 0 ហើយចម្ងាយរវាងបន្ទាត់ទាំងពីរស្មើ d(A, Delta) = 2 (1.5 ពិន្ទុ)', 'សមីការបន្ទាត់', 'medium', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11141, 'គេឱ្យបន្ទាត់ពីរ \(d_1: 2x - y - 3 = 0\) និង \(d_2: x + 2y - 4 = 0\)។
ក. បង្ហាញថាបន្ទាត់ \(d_1\) និង \(d_2\) កែងគ្នា។
ខ. រកកូអរដោនេនៃចំណុចប្រសព្វ \(I\) រវាងបន្ទាត់ទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាញមេគុណប្រាប់ទិស m_1 = 2 និង m_2 = -1/2 (1.5 ពិន្ទុ)
ពិនិត្យផលគុណ m_1 * m_2 = 2 * (-1/2) = -1 នាំឱ្យ d_1 កែង d_2 (1.5 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធសមីការ៖ គុណ d_1 នឹង 2 បាន 4x - 2y - 6 = 0 (1 ពិន្ទុ)
បូកជាមួយ d_2 បាន 5x - 10 = 0 នាំឱ្យ x = 2 និង y = 2(2) - 3 = 1 នាំឱ្យ I(2, 1) (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'medium', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11142, 'គេឱ្យត្រីកោណ \(ABC\) ដែលមានកំពូល \(A(1, 4), B(-2, -2), C(4, 0)\)។
ក. រកសមីការបន្ទាត់ដែលទ្រទ្រង់ជ្រុង \(BC\)។
ខ. រកសមីការបន្ទាត់កម្ពស់ \(AH\) គូសចេញពីកំពូល \(A\) មកជ្រុង \(BC\)។
គ. គណនាប្រវែងកម្ពស់ \(AH\) ដោយប្រើរូបមន្តចម្ងាយពីចំណុចទៅបន្ទាត់។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាមេគុណប្រាប់ទិស m_{BC} = (0 - (-2))/(4 - (-2)) = 2/6 = 1/3 (1 ពិន្ទុ)
សមីការជ្រុង BC: y - 0 = (1/3)(x - 4) នាំឱ្យ x - 3y - 4 = 0 (1 ពិន្ទុ)
ដោយ AH កែង BC នាំឱ្យ m_{AH} = -3; សមីការ AH: y - 4 = -3(x - 1) នាំឱ្យ 3x + y - 7 = 0 (1.5 ពិន្ទុ)
គណនាប្រវែង AH = |1(1) - 3(4) - 4| / sqrt(1^2 + (-3)^2) = |-15| / sqrt(10) = 15/sqrt(10) = 1.5*sqrt(10) (1.5 ពិន្ទុ)', 'សមីការបន្ទាត់', 'hard', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11143, 'រកសមីការបន្ទាត់ \(d\) ដែលកាត់តាមចំណុច \(P(3, 1)\) ហើយមានចម្ងាយពីគល់កូអរដោនេ \(O(0, 0)\) ស្មើនឹង \(1\)។
ក. សរសេរសមីការបន្ទាត់ \(d\) តាមមេគុណប្រាប់ទិស \(m\) (សន្មតបន្ទាត់មិនឈរ)។
ខ. អនុវត្តលក្ខខណ្ឌចម្ងាយ \(d(O, d) = 1\) ដើម្បីដោះស្រាយរក \(m\)។
គ. សរសេរសមីការបន្ទាត់ចម្លើយទាំងអស់ (ពិនិត្យករណីបន្ទាត់ឈរផងដែរ)។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងសមីការ d: y - 1 = m(x - 3) នាំឱ្យ mx - y + (1 - 3m) = 0 (1 ពិន្ទុ)
អនុវត្តរូបមន្តចម្ងាយ: |1 - 3m| / sqrt(m^2 + 1) = 1 នាំឱ្យ (1 - 3m)^2 = m^2 + 1 (1.5 ពិន្ទុ)
ពន្លាត 1 - 6m + 9m^2 = m^2 + 1 នាំឱ្យ 8m^2 - 6m = 0 នាំឱ្យ 2m(4m - 3) = 0 (1 ពិន្ទុ)
ទាញបាន m = 0 ឬ m = 3/4 (0.5 ពិន្ទុ)
សមីការទីមួយ (m=0): y = 1; សមីការទីពីរ (m=3/4): 3x - 4y - 5 = 0 (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'hard', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11144, 'គេឱ្យបន្ទាត់ពីរ \(d_1: x + 2y - 5 = 0\) និង \(d_2: 2x - y + 1 = 0\)។
ក. បង្ហាញថាបន្ទាត់ទាំងពីរកែងគ្នាត្រង់ចំណុច \(I\) មួយ រួចរកកូអរដោនេនៃ \(I\)។
ខ. រកសមីការបន្ទាត់ពុះមុំរវាងបន្ទាត់ \(d_1\) និង \(d_2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ពិនិត្យលក្ខខណ្ឌកែងគ្នា: a_1 a_2 + b_1 b_2 = 1(2) + 2(-1) = 0 នាំឱ្យ d_1 កែង d_2 (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធរកប្រសព្វ: 2(d_1) + d_2 នាំឱ្យ 2(5) - 1 = 5y នាំឱ្យ y = 2, x = 1 នាំឱ្យ I(1, 2) (1.5 ពិន្ទុ)
សមីការបន្ទាត់ពុះមុំ: |x + 2y - 5| / sqrt(5) = |2x - y + 1| / sqrt(5) (1 ពិន្ទុ)
ករណី 1: x + 2y - 5 = 2x - y + 1 នាំឱ្យ x - 3y + 6 = 0 (0.75 ពិន្ទុ)
ករណី 2: x + 2y - 5 = -(2x - y + 1) នាំឱ្យ 3x + y - 4 = 0 (0.75 ពិន្ទុ)', 'សមីការបន្ទាត់', 'hard', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11145, 'ត្រីកោណ \(ABC\) មានកំពូល \(A(2, 5)\) និងសមីការបន្ទាត់មេដ្យានពីរគឺ \(m_1: x + y - 4 = 0\) និង \(m_2: 2x - y - 2 = 0\)។
ក. រកកូអរដោនេនៃទីប្រជុំទម្ងន់ \(G\) នៃត្រីកោណ \(ABC\)។
ខ. រកកូអរដោនេនៃចំណុចកណ្ដាល \(M\) នៃជ្រុង \(BC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ទីប្រជុំទម្ងន់ G ជាចំណុចប្រសព្វនៃមេដ្យានទាំងពីរ m_1 និង m_2 (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធ: បូក m_1 និង m_2 បាន 3x - 6 = 0 នាំឱ្យ x = 2 (1 ពិន្ទុ)
ជំនួស x = 2 ក្នុង m_1 បាន 2 + y - 4 = 0 នាំឱ្យ y = 2 ដូចនេះ G(2, 2) (1 ពិន្ទុ)
ប្រើទំនាក់ទំនងវ៉ិចទ័រ AG = 2 GM នាំឱ្យ G ចែក AM តាមផលធៀប 2:1 (1 ពិន្ទុ)
គណនា x_M = (3x_G - x_A)/2 = (6 - 2)/2 = 2 និង y_M = (3y_G - y_A)/2 = (6 - 5)/2 = 0.5 នាំឱ្យ M(2, 0.5) (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'hard', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11146, 'ក្រុមហ៊ុនវិស្វកម្មរចនាស្ពានអាកាសមួយដែលមានផ្លូវឡើងជាបន្ទាត់ត្រង់កាត់តាមចំណុច \(A(0, 5)\) និង \(B(50, 15)\) (គិតជាម៉ែត្រ)។
ក. គណនាមេគុណប្រាប់ទិស (ចំណោត) នៃផ្លូវឡើងស្ពានអាកាសនោះ។
ខ. សរសេរសមីការកម្ពស់ផ្លូវ \(y\) ជាអនុគមន៍នៃចម្ងាយដេក \(x\)។
គ. រកកម្ពស់ស្ពាននៅត្រង់ចំណុច \(x = 30\text{ m}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាមេគុណប្រាប់ទិស m = (15 - 5)/(50 - 0) = 10/50 = 0.2 (ស្មើ 20%) (1.5 ពិន្ទុ)
សរសេរសមីការបន្ទាត់ y = mx + b ដោយ b = 5 បាន y = 0.2x + 5 (1.5 ពិន្ទុ)
ជំនួស x = 30 ចូលក្នុងសមីការ: y = 0.2(30) + 5 = 6 + 5 = 11 ម៉ែត្រ (2 ពិន្ទុ)', 'សមីការបន្ទាត់', 'pisa', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11147, 'ស្ថានីយ៍វិទ្យុទាក់ទងមួយស្ថិតនៅចំណុច \(S(1, 2)\) (គិតជាគីឡូម៉ែត្រ)។ ផ្លូវជាតិមួយខ្សែមានគន្លងត្រង់កំណត់ដោយសមីការ \(3x + 4y - 36 = 0\)។
ក. គណនាចម្ងាយកាត់កែងជិតបំផុតពីស្ថានីយ៍វិទ្យុទៅផ្លូវជាតិនោះ។
ខ. បើឧបករណ៍បញ្ជូនសញ្ញារបស់ស្ថានីយ៍មានកាំគ្របដណ្តប់ \(R = 4.5\text{ km}\) តើរថយន្តដែលបើកបរលើផ្លូវជាតិនោះអាចចាប់សញ្ញាវិទ្យុបានដែរឬទេ? ពន្យល់។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តចម្ងាយពីចំណុចទៅបន្ទាត់ d = |ax_0 + by_0 + c| / sqrt(a^2 + b^2) (1.5 ពិន្ទុ)
ជំនួស S(1, 2) គណនា d = |3(1) + 4(2) - 36| / sqrt(3^2 + 4^2) = |11 - 36| / 5 = 25 / 5 = 5 km (1.5 ពិន្ទុ)
ប្រៀបធៀបចម្ងាយជិតបំផុត d = 5 km ជាមួយកាំគ្របដណ្តប់ R = 4.5 km (1 ពិន្ទុ)
សន្និដ្ឋានថារថយន្តមិនអាចចាប់សញ្ញាបានទេ ព្រោះ d > R (5 > 4.5) (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'pisa', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11148, 'សហគ្រាសផលិតទឹកផ្លែឈើមួយមានចំណាយថេរប្រចាំខែ \(1\,200\) ដុល្លារ និងថ្លៃដើមផលិតក្នុងមួយដប \(0.5\) ដុល្លារ។
ក. សរសេរសមីការចំណាយសរុប \(C(x)\) ក្នុងការផលិតទឹកផ្លែឈើ \(x\) ដប។
ខ. បើគេលក់ក្នុងតម្លៃ \(1.5\) ដុល្លារក្នុងមួយដប សរសេរសមីការប្រាក់ចំណូលសរុប \(R(x)\)។
គ. រកបរិមាណដបទឹកផ្លែឈើដែលត្រូវផលិតនិងលក់ដើម្បីបានចំនុចរួចដើម (Break-even point)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរសមីការចំណាយសរុប C(x) = 0.5x + 1,200 (1.5 ពិន្ទុ)
សរសេរសមីការចំណូល R(x) = 1.5x (1 ពិន្ទុ)
កំណត់លក្ខខណ្ឌរួចដើម R(x) = C(x) នាំឱ្យ 1.5x = 0.5x + 1,200 (1 ពិន្ទុ)
ដោះស្រាយសមីការ 1.0x = 1,200 នាំឱ្យ x = 1,200 ដប (1.5 ពិន្ទុ)', 'សមីការបន្ទាត់', 'pisa', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11149, 'បំពង់បង្ហូរទឹកស្អាតកាត់តាមចំណុច \(A(0, 2)\) និង \(B(6, 5)\)។ ផ្ទះប្រជាពលរដ្ឋមួយខ្នងស្ថិតនៅចំណុច \(H(4, 8)\) (គិតជាដប់ម៉ែត្រ)។
ក. សរសេរសមីការបន្ទាត់នៃបំពង់ទឹកស្អាត \(AB\)។
ខ. គណនាប្រវែងបំពង់តភ្ជាប់កាត់កែងដែលខ្លីបំផុតពីផ្ទះ \(H\) មកបំពង់មេ \(AB\) គិតជាម៉ែត្រ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាមេគុណប្រាប់ទិស m = (5 - 2)/(6 - 0) = 3/6 = 0.5 (1 ពិន្ទុ)
សរសេរសមីការបន្ទាត់ y = 0.5x + 2 នាំឱ្យ x - 2y + 4 = 0 (1.5 ពិន្ទុ)
គណនាចម្ងាយ d = |1(4) - 2(8) + 4| / sqrt(1^2 + (-2)^2) = |4 - 16 + 4| / sqrt(5) = 8 / sqrt(5) ឯកតា (1.5 ពិន្ទុ)
បំប្លែងទៅជាម៉ែត្រ (1 ឯកតា = 10m): d = (80 / sqrt(5)) ≈ 35.78 ម៉ែត្រ (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'pisa', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11150, 'កប៉ាល់ដឹកទំនិញពីរធ្វើដំណើរកាត់មហាសមុទ្រតាមគន្លងបន្ទាត់ត្រង់។ កប៉ាល់ A ធ្វើដំណើរតាមបន្ទាត់ \(y = 2x - 1\) និងកប៉ាល់ B ធ្វើដំណើរតាមបន្ទាត់ \(x + y - 8 = 0\) (គិតជាម៉ាយល៍សមុទ្រ)។
ក. រកកូអរដោនេនៃចំណុចប្រសព្វដែលគន្លងកប៉ាល់ទាំងពីរជួបគ្នា។
ខ. គណនាមុំប្រសព្វ \(\theta\) រវាងគន្លងនាវាទាំងពីរ (គណនា \(\tan \theta\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស y = 2x - 1 ចូលក្នុងសមីការទីពីរ: x + (2x - 1) - 8 = 0 (1.5 ពិន្ទុ)
ដោះស្រាយ 3x = 9 នាំឱ្យ x = 3 និង y = 2(3) - 1 = 5 នាំឱ្យចំណុចប្រសព្វគឺ (3, 5) (1.5 ពិន្ទុ)
កំណត់មេគុណប្រាប់ទិស m_1 = 2 និង m_2 = -1 (1 ពិន្ទុ)
អនុវត្តរូបមន្ត tan theta = |(m_2 - m_1)/(1 + m_1 m_2)| = |(-1 - 2)/(1 + 2(-1))| = |-3 / -1| = 3 (1 ពិន្ទុ)', 'សមីការបន្ទាត់', 'pisa', 0, '10', 'សមីការបន្ទាត់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
