INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11201, 'តាមរូបភាព សមីការស្តង់ដានៃរង្វង់ដែលមានផ្ចិត \(I(a, b)\) និងកាំ \(R\) គឺ៖', 'g10-fbb5a4a85b.svg', '["\\((x - a)^2 + (y - b)^2 = R^2\\)", "\\((x - a)^2 - (y - b)^2 = R^2\\)", "\\((x + a)^2 + (y + b)^2 = R^2\\)", "\\((x - a) + (y - b) = R\\)"]', 0, NULL, 1, 'mcq', 'នេះជានិយមន័យសមីការស្តង់ដានៃរង្វង់ក្នុងប្លង់កូអរដោនេ។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11202, 'រង្វង់ \(x^2 + y^2 - 4x + 6y - 12 = 0\) មានផ្ចិត \(I\) ស្មើនឹង៖', NULL, '["\\((2, -3)\\)", "\\((4, -6)\\)", "\\((-2, 3)\\)", "\\((-4, 6)\\)"]', 0, NULL, 1, 'mcq', '\(a = -\dfrac{-4}{2} = 2, \quad b = -\dfrac{6}{2} = -3 \implies I(2, -3)\)។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-dffb5c6ac5.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11203, 'តាមរូបភាព សមីការរង្វង់ដែលមានអង្កត់ផ្ចិត \(AB\) ដោយ \(A(x_A, y_A)\) និង \(B(x_B, y_B)\) គឺ៖', 'g10-dffb5c6ac5.svg', '["\\((x - x_A)(x - x_B) + (y - y_A)(y - y_B) = 0\\)", "\\((x - x_A)^2 + (y - y_B)^2 = 0\\)", "\\((x - x_A)(y - y_A) + (x - x_B)(y - y_B) = 0\\)", "\\((x + x_A)(x + x_B) + (y + y_A)(y + y_B) = 0\\)"]', 0, NULL, 1, 'mcq', 'គ្រប់ចំណុច P លើរង្វង់បង្កើតបាន \(\vec{PA} \cdot \vec{PB} = 0 \implies (x - x_A)(x - x_B) + (y - y_A)(y - y_B) = 0\)។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-363e8e282e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11204, 'តាមរូបភាព បន្ទាត់ \(\Delta\) ប៉ះរង្វង់ផ្ចិត \(I\) កាំ \(R\) លុះត្រាតែចម្ងាយ \(d(I, \Delta)\) ស្មើនឹង៖', 'g10-363e8e282e.svg', '["\\(2R\\)", "\\(0\\)", "\\(R\\)", "\\(\\dfrac{R}{2}\\)"]', 2, NULL, 1, 'mcq', 'លក្ខខណ្ឌប៉ះនៃបន្ទាត់និងរង្វង់គឺចម្ងាយពីផ្ចិតទៅបន្ទាត់ស្មើនឹងកាំ \(d = R\)។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-d7a847bd7f.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11205, 'តាមរូបភាព បើចម្ងាយពីផ្ចិតរង្វង់ទៅបន្ទាត់មួយ \(d < R\) នោះបន្ទាត់និងរង្វង់មានទីតាំងធៀបដូចម្តេច?', 'g10-d7a847bd7f.svg', '["បន្ទាត់កាត់រង្វង់ត្រង់ពីរចំណុច (ខណ្ឌសេកង់)", "បន្ទាត់ប៉ះរង្វង់ត្រង់មួយចំណុច", "បន្ទាត់នៅក្រៅរង្វង់ (គ្មានចំណុចរួម)", "បន្ទាត់កាត់តាមផ្ចិតរង្វង់ជានិច្ច"]', 0, NULL, 1, 'mcq', 'កាលណា \(d < R\) បន្ទាត់កាត់រង្វង់ត្រង់ ២ ចំណុចផ្សេងគ្នា។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11206, 'ផ្ចិត \(I\) និងកាំ \(R\) នៃរង្វង់ \((x - 3)^2 + (y + 2)^2 = 16\) គឺ៖', NULL, '["\\(I(3, -2), \\ R = 4\\)", "\\(I(-3, 2), \\ R = 4\\)", "\\(I(3, -2), \\ R = 16\\)", "\\(I(-3, 2), \\ R = 16\\)"]', 0, NULL, 1, 'mcq', 'ពី \((x - 3)^2 + (y - (-2))^2 = 4^2 \implies I(3, -2)\) និង \(R = 4\)។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11207, 'លក្ខខណ្ឌដើម្បីឱ្យសមីការ \(x^2 + y^2 - 2ax - 2by + c = 0\) ជារង្វង់ពិតប្រាកដគឺ៖', NULL, '["\\(a^2 + b^2 - c = 0\\)", "\\(a + b - c > 0\\)", "\\(a^2 + b^2 - c > 0\\)", "\\(a^2 + b^2 - c < 0\\)"]', 2, NULL, 1, 'mcq', 'កាំ \(R = \sqrt{a^2 + b^2 - c}\) ដូច្នេះត្រូវការ \(a^2 + b^2 - c > 0\)។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11208, 'សមីការបន្ទាត់ប៉ះនឹងរង្វង់ \(x^2 + y^2 = R^2\) ត្រង់ចំណុច \(T(x_0, y_0)\) លើរង្វង់គឺ៖', NULL, '["\\(x + y = R\\)", "\\(x_0 x + y_0 y = R^2\\)", "\\((x - x_0)^2 + (y - y_0)^2 = R^2\\)", "\\(x_0 x - y_0 y = R^2\\)"]', 1, NULL, 1, 'mcq', 'រូបមន្តបន្ទាត់ប៉ះរង្វង់ផ្ចិតគល់កូអរដោនេត្រង់ចំណុច T គឺ \(x_0 x + y_0 y = R^2\)។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11209, 'សមីការរង្វង់ដែលមានផ្ចិតនៅគល់កូអរដោនេ \(O(0, 0)\) និងកាំ \(R = 5\) គឺ៖', NULL, '["\\(x^2 - y^2 = 25\\)", "\\(x^2 + y^2 = 5\\)", "\\(x^2 + y^2 = 25\\)", "\\((x - 5)^2 + (y - 5)^2 = 0\\)"]', 2, NULL, 1, 'mcq', 'រង្វង់ផ្ចិតគល់កូអរដោនេមានសមីការ \(x^2 + y^2 = R^2 = 5^2 = 25\)។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-95758f4eab.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11210, 'តាមរូបភាព រង្វង់ពីរដែលមានផ្ចិតដូចគ្នា \(I(2, 3)\) តែមានកាំខុសគ្នា \(R_1 = 2\) និង \(R_2 = 4\) ហៅថា៖', 'g10-95758f4eab.svg', '["រង្វង់ប៉ះក្នុង", "រង្វង់អរតូកូណាល់", "រង្វង់រួមផ្ចិត (Concentric circles)", "រង្វង់កាត់គ្នា"]', 2, NULL, 1, 'mcq', 'រង្វង់ដែលមានផ្ចិតត្រួតស៊ីគ្នាហៅថារង្វង់រួមផ្ចិត។', 'សមីការរង្វង់', 'easy', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11211, 'សមីការរង្វង់ដែលមានផ្ចិត \(I(1, -2)\) និងកាត់តាមចំណុច \(A(4, 2)\) គឺ៖', NULL, '["\\((x + 1)^2 + (y - 2)^2 = 25\\)", "\\((x - 1)^2 + (y + 2)^2 = 5\\)", "\\((x - 4)^2 + (y - 2)^2 = 25\\)", "\\((x - 1)^2 + (y + 2)^2 = 25\\)"]', 3, NULL, 2, 'mcq', '\(R^2 = IA^2 = (4 - 1)^2 + (2 - (-2))^2 = 3^2 + 4^2 = 25 \implies (x - 1)^2 + (y + 2)^2 = 25\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11212, 'គណនាកាំ \(R\) នៃរង្វង់ \(x^2 + y^2 - 6x + 8y = 0\)៖', NULL, '["\\(10\\)", "\\(25\\)", "\\(\\sqrt{14}\\)", "\\(5\\)"]', 3, NULL, 2, 'mcq', '\(a = 3, \ b = -4, \ c = 0 \implies R = \sqrt{3^2 + (-4)^2 - 0} = \sqrt{25} = 5\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11213, 'សមីការរង្វង់ដែលមានអង្កត់ផ្ចិត \(AB\) ដោយ \(A(1, 2)\) និង \(B(5, 6)\) គឺ៖', NULL, '["\\((x - 3)^2 + (y - 4)^2 = 32\\)", "\\((x - 1)^2 + (y - 2)^2 = 8\\)", "\\((x - 3)^2 + (y - 4)^2 = 16\\)", "\\((x - 3)^2 + (y - 4)^2 = 8\\)"]', 3, NULL, 2, 'mcq', '\(I = (3, 4), \quad R^2 = \left(\dfrac{AB}{2}\right)^2 = \dfrac{(5-1)^2 + (6-2)^2}{4} = \dfrac{32}{4} = 8\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11214, 'សមីការបន្ទាត់ប៉ះនឹងរង្វង់ \(x^2 + y^2 = 25\) ត្រង់ចំណុច \(T(3, 4)\) គឺ៖', NULL, '["\\(3x + 4y - 25 = 0\\)", "\\(3x + 4y + 25 = 0\\)", "\\(3x - 4y - 25 = 0\\)", "\\(4x - 3y = 0\\)"]', 0, NULL, 2, 'mcq', '\(x_0 x + y_0 y = 25 \implies 3x + 4y - 25 = 0\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11215, 'ពិនិត្យទីតាំងធៀបរវាងបន្ទាត់ \(x + y - 4 = 0\) និងរង្វង់ \(x^2 + y^2 = 8\)៖', NULL, '["បន្ទាត់នៅក្រៅរង្វង់", "បន្ទាត់ប៉ះរង្វង់", "បន្ទាត់កាត់រង្វង់ត្រង់ពីរចំណុច", "បន្ទាត់កាត់តាមផ្ចិតរង្វង់"]', 1, NULL, 2, 'mcq', '\(d = \dfrac{|0 + 0 - 4|}{\sqrt{1^2 + 1^2}} = \dfrac{4}{\sqrt{2}} = 2\sqrt{2} = \sqrt{8} = R \implies d = R\) ដូច្នេះបន្ទាត់ប៉ះរង្វង់។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11216, 'រង្វង់មួយប៉ះអ័ក្សអាប់ស៊ីស \((Ox)\) ហើយមានផ្ចិត \(I(3, -4)\)។ សមីការរង្វង់នោះគឺ៖', NULL, '["\\((x + 3)^2 + (y - 4)^2 = 16\\)", "\\((x - 3)^2 + (y + 4)^2 = 25\\)", "\\((x - 3)^2 + (y + 4)^2 = 9\\)", "\\((x - 3)^2 + (y + 4)^2 = 16\\)"]', 3, NULL, 2, 'mcq', 'រង្វង់ប៉ះអ័ក្ស Ox នាំឱ្យ \(R = |y_I| = |-4| = 4 \implies R^2 = 16\) ដូច្នេះ \((x - 3)^2 + (y + 4)^2 = 16\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11217, 'សមីការ \(x^2 + y^2 - 2x + 4y + 5 = 0\) តាងឱ្យរូបធរណីមាត្រអ្វី?', NULL, '["សំណុំទទេ (គ្មានរូប)", "រង្វង់មានកាំ R = 5", "បន្ទាត់ត្រង់មួយ", "ចំណុចមួយ (1, -2)"]', 3, NULL, 2, 'mcq', '\(a = 1, b = -2, c = 5 \implies a^2 + b^2 - c = 1^2 + (-2)^2 - 5 = 0 \implies (x-1)^2 + (y+2)^2 = 0\) តាងឱ្យចំណុចតែមួយគត់ \((1, -2)\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11218, 'សមីការបន្ទាត់ប៉ះនឹងរង្វង់ \((x - 1)^2 + (y - 2)^2 = 10\) ត្រង់ចំណុច \(T(4, 3)\) គឺ៖', NULL, '["\\(3x + y + 15 = 0\\)", "\\(x + 3y - 13 = 0\\)", "\\(3x + y - 15 = 0\\)", "\\(3x - y - 11 = 0\\)"]', 2, NULL, 2, 'mcq', '\((4 - 1)(x - 1) + (3 - 2)(y - 2) = 10 \implies 3(x - 1) + 1(y - 2) = 10 \implies 3x + y - 15 = 0\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11219, 'ចំណុចប្រសព្វរវាងរង្វង់ \(x^2 + y^2 = 25\) និងបន្ទាត់ \(y = x - 1\) គឺ៖', NULL, '["\\((4, 3) \\text{ និង } (-3, -4)\\)", "\\((4, -3) \\text{ និង } (-3, 4)\\)", "\\((5, 0) \\text{ និង } (0, -5)\\)", "\\((3, 4) \\text{ និង } (-4, -3)\\)"]', 0, NULL, 2, 'mcq', '\(x^2 + (x-1)^2 = 25 \implies 2x^2 - 2x - 24 = 0 \implies x^2 - x - 12 = 0 \implies x = 4 \text{ ឬ } x = -3\) នាំឱ្យ \((4, 3)\) និង \((-3, -4)\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11220, 'រង្វង់មួយប៉ះអ័ក្សអ័រដោនេ \((Oy)\) ហើយមានផ្ចិត \(I(-5, 2)\)។ សមីការរង្វង់នោះគឺ៖', NULL, '["\\((x + 5)^2 + (y - 2)^2 = 29\\)", "\\((x - 5)^2 + (y + 2)^2 = 25\\)", "\\((x + 5)^2 + (y - 2)^2 = 4\\)", "\\((x + 5)^2 + (y - 2)^2 = 25\\)"]', 3, NULL, 2, 'mcq', 'រង្វង់ប៉ះអ័ក្ស Oy នាំឱ្យ \(R = |x_I| = |-5| = 5 \implies R^2 = 25\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11221, 'សមីការ \(x^2 + y^2 - 4x - 6y + 15 = 0\) តាងឱ្យ៖', NULL, '["សំណុំទទេ (គ្មានចំណុចក្នុងប្លង់)", "រង្វង់កាំ R = 2", "ចំណុច (2, 3)", "រង្វង់កាំ R = 15"]', 0, NULL, 2, 'mcq', '\(a = 2, b = 3, c = 15 \implies a^2 + b^2 - c = 4 + 9 - 15 = -2 < 0\) នាំឱ្យគ្មានចំណុចផ្ទៀងផ្ទាត់ (សំណុំទទេ)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11222, 'ប្រវែងបន្ទាត់ប៉ះ \(PT\) គូសពីចំណុចក្រៅ \(P(5, 0)\) ទៅកាន់រង្វង់ \(x^2 + y^2 = 9\) គឺ៖', NULL, '["\\(5\\)", "\\(\\sqrt{34}\\)", "\\(3\\)", "\\(4\\)"]', 3, NULL, 2, 'mcq', 'ត្រីកោណ \(PTI\) កែងត្រង់ T នាំឱ្យ \(PT = \sqrt{OP^2 - R^2} = \sqrt{5^2 - 3^2} = \sqrt{16} = 4\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11223, 'រង្វង់មួយមានផ្ចិត \(I(2, 3)\) និងប៉ះបន្ទាត់ \(3x + 4y - 8 = 0\)។ កាំ \(R\) នៃរង្វង់គឺ៖', NULL, '["\\(4\\)", "\\(2\\)", "\\(1\\)", "\\(3\\)"]', 1, NULL, 2, 'mcq', '\(R = d(I, \Delta) = \dfrac{|3(2) + 4(3) - 8|}{\sqrt{3^2 + 4^2}} = \dfrac{|6 + 12 - 8|}{5} = \dfrac{10}{5} = 2\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11224, 'រកតម្លៃ \(m\) ដើម្បីឱ្យសមីការ \(x^2 + y^2 - 4x + 2y + m = 0\) ជារង្វង់ដែលមានកាំ \(R = 3\)៖', NULL, '["\\(5\\)", "\\(4\\)", "\\(-5\\)", "\\(-4\\)"]', 3, NULL, 2, 'mcq', '\(a = 2, b = -1 \implies R^2 = a^2 + b^2 - m \implies 9 = 4 + 1 - m \implies 9 = 5 - m \implies m = -4\)។', 'សមីការរង្វង់', 'medium', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11225, 'សមីការរង្វង់កាត់តាមបីចំណុច \(O(0, 0), A(4, 0), B(0, 6)\) គឺ៖', NULL, '["\\(x^2 + y^2 - 2x - 3y = 0\\)", "\\(x^2 + y^2 - 4x - 6y = 0\\)", "\\(x^2 + y^2 + 4x + 6y = 0\\)", "\\((x - 4)^2 + (y - 6)^2 = 25\\)"]', 1, NULL, 3, 'mcq', 'ត្រីកោណ OAB កែងត្រង់ O នាំឱ្យ AB ជាអង្កត់ផ្ចិត ៖ \((x-4)(x-0) + (y-0)(y-6) = 0 \implies x^2 + y^2 - 4x - 6y = 0\)។', 'សមីការរង្វង់', 'hard', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11226, 'សមីការបន្ទាត់ប៉ះនឹងរង្វង់ \(x^2 + y^2 = 5\) ដែលស្របនឹងបន្ទាត់ \(2x - y + 1 = 0\) គឺ៖', NULL, '["\\(2x - y + \\sqrt{5} = 0 \\text{ ឬ } 2x - y - \\sqrt{5} = 0\\)", "\\(x + 2y + 5 = 0 \\text{ ឬ } x + 2y - 5 = 0\\)", "\\(2x - y + 10 = 0 \\text{ ឬ } 2x - y - 10 = 0\\)", "\\(2x - y + 5 = 0 \\text{ ឬ } 2x - y - 5 = 0\\)"]', 3, NULL, 3, 'mcq', 'បន្ទាត់ប៉ះមានរាង \(2x - y + c = 0\)។ \(d = \dfrac{|c|}{\sqrt{2^2 + (-1)^2}} = \sqrt{5} \implies \dfrac{|c|}{\sqrt{5}} = \sqrt{5} \implies |c| = 5 \implies c = \pm 5\)។', 'សមីការរង្វង់', 'hard', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11227, 'ប្រវែងអង្កត់ធ្នូរួមនៃរង្វង់ពីរ \(C_1: x^2 + y^2 = 25\) និង \(C_2: (x - 4)^2 + y^2 = 9\) គឺ៖', NULL, '["\\(5\\)", "\\(6\\)", "\\(4.8\\)", "រង្វង់ទាំងពីរប៉ះក្នុងគ្នាត្រង់ចំណុច (3, 0) (ប្រវែង 0)"]', 3, NULL, 3, 'mcq', '\(I_1(0, 0), R_1 = 5; \ I_2(4, 0), R_2 = 3 \implies I_1 I_2 = 4 = R_1 - R_2\) ដូច្នេះរង្វង់ទាំងពីរប៉ះក្នុងគ្នាត្រង់ចំណុចតែមួយ។', 'សមីការរង្វង់', 'hard', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11228, 'សមីការរង្វង់ដែលមានផ្ចិតនៅលើបន្ទាត់ \(y = x\) ហើយប៉ះបន្ទាត់ទាំងពីរ \(x = 1\) និង \(x = 5\) គឺ៖', NULL, '["\\((x - 3)^2 + (y - 3)^2 = 16\\)", "\\((x - 2)^2 + (y - 2)^2 = 4\\)", "\\((x - 3)^2 + (y - 3)^2 = 2\\)", "\\((x - 3)^2 + (y - 3)^2 = 4\\)"]', 3, NULL, 3, 'mcq', 'ផ្ចិតនៅកណ្ដាលរវាង x=1 និង x=5 នាំឱ្យ \(a = (1+5)/2 = 3 \implies b = 3\) ហើយកាំ \(R = (5-1)/2 = 2 \implies R^2 = 4\)។', 'សមីការរង្វង់', 'hard', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11229, 'ពីចំណុច \(A(0, 5)\) គេគូសបន្ទាត់ប៉ះពីរទៅកាន់រង្វង់ \(x^2 + y^2 = 9\)។ មេគុណប្រាប់ទិសនៃបន្ទាត់ប៉ះទាំងពីរគឺ៖', NULL, '["\\(m = \\pm \\dfrac{4}{3}\\)", "\\(m = \\pm 2\\)", "\\(m = \\pm 1\\)", "\\(m = \\pm \\dfrac{3}{4}\\)"]', 0, NULL, 3, 'mcq', 'បន្ទាត់កាត់ A(0, 5) មានរាង \(mx - y + 5 = 0\)។ \(d = \dfrac{|5|}{\sqrt{m^2 + 1}} = 3 \implies 9(m^2 + 1) = 25 \implies 9m^2 = 16 \implies m = \pm \dfrac{4}{3}\)។', 'សមីការរង្វង់', 'hard', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11230, 'រង្វង់ \(C\) ប៉ះអ័ក្សទាំងពីរ \(Ox\) និង \(Oy\) ក្នុងកាដ្រង់ទី 1 ហើយកាត់តាមចំណុច \(P(2, 1)\)។ កាំ \(R\) អាចស្មើនឹង៖', NULL, '["\\(1 \\text{ ឬ } 3\\)", "\\(1 \\text{ ឬ } 5\\)", "\\(3 \\text{ ឬ } 6\\)", "\\(2 \\text{ ឬ } 4\\)"]', 1, NULL, 3, 'mcq', 'ផ្ចិត \(I(R, R) \implies (2 - R)^2 + (1 - R)^2 = R^2 \implies R^2 - 6R + 5 = 0 \implies R = 1 \text{ ឬ } R = 5\)។', 'សមីការរង្វង់', 'hard', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11231, 'មុំរវាងបន្ទាត់ប៉ះទាំងពីរដែលគូសចេញពីចំណុច \(P(2R, 0)\) ទៅកាន់រង្វង់ \(x^2 + y^2 = R^2\) គឺ៖', NULL, '["\\(120^\\\\circ\\)", "\\(60^\\\\circ\\)", "\\(90^\\\\circ\\)", "\\(45^\\\\circ\\)"]', 1, NULL, 3, 'mcq', '\(\sin \alpha = \dfrac{R}{OP} = \dfrac{R}{2R} = \dfrac{1}{2} \implies \alpha = 30^\circ \implies 2\alpha = 60^\circ\)។', 'សមីការរង្វង់', 'hard', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11232, 'បង្គោលបញ្ជូនសញ្ញា Wi-Fi មួយត្រូវបានដំឡើងនៅកណ្តាលសាលារៀនត្រង់ចំណុច \(C(3, 4)\) (គិតជាដប់ម៉ែត្រ)។ សញ្ញា Wi-Fi អាចគ្របដណ្តប់បានចម្ងាយអតិបរមា \(50\\text{ m}\) (5 ឯកតា)។ សមីការព្រំប្រទល់ដែនគ្របដណ្តប់នៃសញ្ញា Wi-Fi គឺ៖', NULL, '["\\((x - 3)^2 + (y - 4)^2 = 50\\)", "\\((x - 3)^2 + (y - 4)^2 = 5\\)", "\\((x + 3)^2 + (y + 4)^2 = 25\\)", "\\((x - 3)^2 + (y - 4)^2 = 25\\)"]', 3, NULL, 3, 'mcq', 'រង្វង់មានផ្ចិត \((3, 4)\) និងកាំ \(R = 5 \implies (x - 3)^2 + (y - 4)^2 = 25\)។', 'សមីការរង្វង់', 'pisa', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11233, 'ក្បាលបាញ់ទឹកវិលស្វ័យប្រវត្តិកំពុងស្រោចស្រពសួនស្មៅរាងជារង្វង់ដែលមានសមីការ \(x^2 + y^2 - 8x - 6y = 0\) (គិតជាម៉ែត្រ)។ ផ្ទៃក្រឡាសួនស្មៅដែលទទួលបានទឹកស្រោចស្រពគឺ៖', NULL, '["\\(25\\\\pi\\\\text{ m}^2 \\\\approx 78.54\\\\text{ m}^2\\)", "\\(50\\\\pi\\\\text{ m}^2\\)", "\\(100\\\\pi\\\\text{ m}^2\\)", "\\(16\\\\pi\\\\text{ m}^2\\)"]', 0, NULL, 3, 'mcq', '\(a = 4, b = 3, c = 0 \implies R = \sqrt{16 + 9} = 5\text{ m} \implies S = \pi R^2 = 25\pi\text{ m}^2\)។', 'សមីការរង្វង់', 'pisa', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11234, 'ស្ថានីយ៍រ៉ាដាដែនសមុទ្រមួយនៅកោះកុងអាចចាប់សញ្ញានាវាបានក្នុងរង្វង់ \(x^2 + y^2 = 100\) (គិតជាគីឡូម៉ែត្រ)។ នាវាដឹកប្រេងមួយកំពុងស្ថិតនៅកូអរដោនេ \(S(6, 8)\)។ នាវានោះស្ថិតនៅទីតាំងណាធៀបនឹងដែនរ៉ាដា?', NULL, '["ស្ថិតនៅចំផ្ចិតរ៉ាដា", "ស្ថិតនៅលើគែមព្រំប្រទល់រ៉ាដាល្មម", "ស្ថិតនៅក្រៅដែនរ៉ាដា", "ស្ថិតនៅខាងក្នុងដែនរ៉ាដា"]', 1, NULL, 3, 'mcq', '\(d^2 = 6^2 + 8^2 = 36 + 64 = 100 = R^2\) ដូច្នេះនាវាស្ថិតនៅលើគែមរង្វង់ព្រំប្រទល់ល្មម។', 'សមីការរង្វង់', 'pisa', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11235, 'ឧបករណ៍ចាប់រលកញ័ររញ្ជួយដី (Seismograph) កំណត់ថាចំណុចកណ្តាលនៃការរញ្ជួយដី (Epicenter) ស្ថិតនៅលើរង្វង់ \((x - 2)^2 + (y - 5)^2 = 25\)។ ទីប្រជុំជនមួយស្ថិតនៅ \(T(5, 9)\) (គិតជាគីឡូម៉ែត្រ)។ តើទីប្រជុំជននេះអាចជាចំណុចកណ្តាលនៃការរញ្ជួយដីដែរឬទេ?', NULL, '["មិនអាច ព្រោះចំណុច T ស្ថិតក្នុងរង្វង់", "មិនអាចកំណត់បាន", "មិនអាច ព្រោះចំណុច T ស្ថិតនៅក្រៅរង្វង់", "អាច ព្រោះចំណុច T ស្ថិតនៅលើរង្វង់ទិន្នន័យ"]', 3, NULL, 3, 'mcq', '\((5 - 2)^2 + (9 - 5)^2 = 3^2 + 4^2 = 9 + 16 = 25\) ផ្ទៀងផ្ទាត់សមីការ ដូច្នេះ T ស្ថិតនៅលើរង្វង់។', 'សមីការរង្វង់', 'pisa', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11236, 'ផ្លូវដែករាងជារង្វង់មូលមួយមានកណ្តាលនៅ \(O(0, 0)\) និងកាំ \(R = 10\\text{ km}\)។ ផ្លូវលំត្រង់មួយខ្សែរត់តាមសមីការ \(3x + 4y - 50 = 0\)។ តើផ្លូវលំនេះមានចំណុចប្រសព្វឆ្លងកាត់ផ្លូវដែកប៉ុន្មានកន្លែង?', NULL, '["កាត់គ្នាត្រង់ ៣ កន្លែង", "កាត់គ្នាត្រង់ ២ កន្លែង", "មិនជួបគ្នាទាល់តែសោះ (០ កន្លែង)", "ប៉ះគ្នាត្រង់ ១ កន្លែងប៉ុណ្ណោះ"]', 3, NULL, 3, 'mcq', '\(d = \dfrac{|3(0) + 4(0) - 50|}{\sqrt{3^2 + 4^2}} = \dfrac{50}{5} = 10\text{ km} = R\) នាំឱ្យផ្លូវលំប៉ះផ្លូវដែកត្រង់ ១ កន្លែង។', 'សមីការរង្វង់', 'pisa', 1, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11237, 'គេឱ្យចំណុច \(I(2, -3)\) និងចំនួនពិត \(R = 4\)។
ក. សរសេរសមីការស្តង់ដានៃរង្វង់ដែលមានផ្ចិត \(I\) និងកាំ \(R\)។
ខ. ពន្លាតសមីការនោះឱ្យទៅជាទម្រង់ទូទៅ \(x^2 + y^2 - 2ax - 2by + c = 0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តសមីការស្តង់ដា (x - a)^2 + (y - b)^2 = R^2 (1 ពិន្ទុ)
ជំនួសតម្លៃ a = 2, b = -3, R = 4 បាន (x - 2)^2 + (y + 3)^2 = 16 (1.5 ពិន្ទុ)
ពន្លាតពិជគណិត x^2 - 4x + 4 + y^2 + 6y + 9 = 16 (1.5 ពិន្ទុ)
បង្រួមជាទម្រង់ទូទៅ x^2 + y^2 - 4x + 6y - 3 = 0 (1 ពិន្ទុ)', 'សមីការរង្វង់', 'easy', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11238, 'គេឱ្យសមីការ \(x^2 + y^2 - 6x + 4y - 12 = 0\)។
ក. បង្ហាញថាសមីការខាងលើជារង្វង់ រួចកំណត់កូអរដោនេផ្ចិត \(I\) និងកាំ \(R\) នៃរង្វង់នោះ។
ខ. ពិនិត្យទីតាំងនៃចំណុច \(P(6, 2)\) ធៀបនឹងរង្វង់នេះ (នៅខាងក្នុង លើ ឬខាងក្រៅរង្វង់)។', NULL, '[]', 0, NULL, 5, 'writing', 'បំប្លែងជាការេពេញ: (x^2 - 6x + 9) + (y^2 + 4y + 4) = 12 + 9 + 4 (1.5 ពិន្ទុ)
ទាញបានទម្រង់ស្តង់ដា (x - 3)^2 + (y + 2)^2 = 25 (1 ពិន្ទុ)
កំណត់កូអរដោនេផ្ចិត I(3, -2) និងកាំ R = sqrt(25) = 5 (1 ពិន្ទុ)
គណនាចម្ងាយ IP^2 = (6 - 3)^2 + (2 - (-2))^2 = 3^2 + 4^2 = 25 = R^2 (1 ពិន្ទុ)
សន្និដ្ឋានថាចំណុច P(6, 2) ស្ថិតនៅលើរង្វង់ (0.5 ពិន្ទុ)', 'សមីការរង្វង់', 'medium', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11239, 'គេឱ្យពីរចំណុច \(A(-1, 3)\) និង \(B(5, -5)\)។
ក. រកកូអរដោនេនៃចំណុចកណ្ដាល \(I\) នៃអង្កត់ \(AB\) និងគណនាប្រវែង \(AB\)។
ខ. សរសេរសមីការរង្វង់ដែលមាន \(AB\) ជាអង្កត់ផ្ចិត។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាកូអរដោនេផ្ចិត I: x_I = (-1+5)/2 = 2, y_I = (3-5)/2 = -1 នាំឱ្យ I(2, -1) (1.5 ពិន្ទុ)
គណនាប្រវែងអង្កត់ផ្ចិត AB = sqrt((5 - (-1))^2 + (-5 - 3)^2) = sqrt(36 + 64) = 10 (1.5 ពិន្ទុ)
ទាញរកកាំ R = AB / 2 = 5 នាំឱ្យ R^2 = 25 (1 ពិន្ទុ)
សរសេរសមីការរង្វង់ (x - 2)^2 + (y + 1)^2 = 25 (1 ពិន្ទុ)', 'សមីការរង្វង់', 'medium', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11240, 'គេឱ្យរង្វង់ \(C: x^2 + y^2 = 20\) និងចំណុច \(T(4, -2)\)។
ក. បង្ហាញថាចំណុច \(T\) ស្ថិតនៅលើរង្វង់ \(C\)។
ខ. សរសេរសមីការបន្ទាត់ \(\Delta\) ដែលប៉ះនឹងរង្វង់ \(C\) ត្រង់ចំណុច \(T\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស T(4, -2) ចូលក្នុងសមីការរង្វង់: 4^2 + (-2)^2 = 16 + 4 = 20 (1.5 ពិន្ទុ)
សន្និដ្ឋានថា T(4, -2) ស្ថិតនៅលើរង្វង់ C ពិតមែន (1 ពិន្ទុ)
សរសេររូបមន្តបន្ទាត់ប៉ះត្រង់ចំណុច T(x_0, y_0) គឺ x_0 x + y_0 y = R^2 (1 ពិន្ទុ)
ជំនួស x_0 = 4, y_0 = -2 បាន 4x - 2y = 20 (1 ពិន្ទុ)
សម្រួលសមីការចែកនឹង 2 បាន 2x - y - 10 = 0 (0.5 ពិន្ទុ)', 'សមីការរង្វង់', 'medium', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11241, 'គេឱ្យរង្វង់ \(C: x^2 + y^2 - 4 = 0\) និងបន្ទាត់ \(d: x - y + 2 = 0\)។
ក. គណនាចម្ងាយពីផ្ចិតនៃរង្វង់ \(C\) ទៅបន្ទាត់ \(d\)។
ខ. ទាញបញ្ជាក់ថាបន្ទាត់ \(d\) កាត់រង្វង់ \(C\) ត្រង់ពីរចំណុចផ្សេងគ្នា រួចរកកូអរដោនេនៃចំណុចទាំងពីរនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ផ្ចិត I(0, 0) និងកាំ R = 2 (1 ពិន្ទុ)
គណនាចម្ងាយ d(I, d) = |0 - 0 + 2| / sqrt(1^2 + (-1)^2) = 2/sqrt(2) = sqrt(2) (1 ពិន្ទុ)
ប្រៀបធៀប d(I, d) = sqrt(2) < R = 2 នាំឱ្យបន្ទាត់កាត់រង្វង់ត្រង់ពីរចំណុច (1 ពិន្ទុ)
ជំនួស y = x + 2 ចូលរង្វង់: x^2 + (x+2)^2 = 4 នាំឱ្យ 2x^2 + 4x = 0 នាំឱ្យ 2x(x+2) = 0 (1 ពិន្ទុ)
ទាញបាន x = 0 (y = 2) និង x = -2 (y = 0) នាំឱ្យចំណុចទាំងពីរគឺ (0, 2) និង (-2, 0) (1 ពិន្ទុ)', 'សមីការរង្វង់', 'medium', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11242, 'រកសមីការបន្ទាត់ប៉ះនឹងរង្វង់ \(x^2 + y^2 - 2x - 4y + 1 = 0\) ដែលស្របនឹងបន្ទាត់ \(3x + 4y - 5 = 0\)។
ក. កំណត់កូអរដោនេផ្ចិត \(I\) និងកាំ \(R\) នៃរង្វង់។
ខ. សរសេរសមីការបន្ទាត់ប៉ះទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'បំប្លែងជារាងស្តង់ដា (x - 1)^2 + (y - 2)^2 = -1 + 1 + 4 = 4 នាំឱ្យ I(1, 2) និង R = 2 (1.5 ពិន្ទុ)
បន្ទាត់ប៉ះស្របនឹង 3x + 4y - 5 = 0 មានរាង 3x + 4y + c = 0 (1 ពិន្ទុ)
អនុវត្តលក្ខខណ្ឌចម្ងាយ d(I, Delta) = |3(1) + 4(2) + c| / sqrt(3^2 + 4^2) = 2 (1 ពិន្ទុ)
ដោះស្រាយ |11 + c| / 5 = 2 នាំឱ្យ |11 + c| = 10 (0.5 ពិន្ទុ)
ទាញបាន c = -1 ឬ c = -21 នាំឱ្យសមីការបន្ទាត់ប៉ះគឺ 3x + 4y - 1 = 0 និង 3x + 4y - 21 = 0 (1 ពិន្ទុ)', 'សមីការរង្វង់', 'hard', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11243, 'រកសមីការរង្វង់ \(C\) ដែលមានផ្ចិតស្ថិតនៅលើបន្ទាត់ \(d: x - 2y + 3 = 0\) ហើយកាត់តាមពីរចំណុច \(A(1, 1)\) និង \(B(3, 5)\)។
ក. រកសមីការបន្ទាត់មេដ្យាទ័រ \(\Delta\) នៃអង្កត់ \(AB\)។
ខ. រកកូអរដោនេផ្ចិត \(I\) ជាចំណុចប្រសព្វរវាង \(d\) និង \(\Delta\)។
គ. គណនាកាំ \(R\) និងសរសេរសមីការរង្វង់ \(C\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រកចំណុចកណ្ដាល M(2, 3) និងមេគុណប្រាប់ទិស m_{AB} = (5-1)/(3-1) = 2 នាំឱ្យ m_\Delta = -1/2 (1 ពិន្ទុ)
សមីការមេដ្យាទ័រ Delta: y - 3 = -1/2(x - 2) នាំឱ្យ x + 2y - 8 = 0 (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធប្រសព្វរវាង d និង Delta: បូកសមីការបាន 2x - 5 = 0 ... x = 2.5, y = 2.75 (1 ពិន្ទុ)
គណនាកាំ R^2 = IA^2 = (2.5 - 1)^2 + (2.75 - 1)^2 = 1.5^2 + 1.75^2 = 2.25 + 3.0625 = 5.3125 (1 ពិន្ទុ)
សរសេរសមីការរង្វង់ (x - 2.5)^2 + (y - 2.75)^2 = 85/16 (1 ពិន្ទុ)', 'សមីការរង្វង់', 'hard', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11244, 'គេឱ្យរង្វង់ \(C_1: x^2 + y^2 = 10\) និងរង្វង់ \(C_2: x^2 + y^2 - 6x - 6y + 10 = 0\)។
ក. រកសមីការបន្ទាត់អ័ក្សរ៉ាឌីកាល់ (បន្ទាត់កាត់តាមចំណុចប្រសព្វទាំងពីរ) នៃរង្វង់ទាំងពីរ។
ខ. រកកូអរដោនេនៃចំណុចប្រសព្វទាំងពីររវាងរង្វង់ទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដកសមីការ C_1 ពី C_2 បាន (x^2 + y^2 - 6x - 6y + 10) - (x^2 + y^2 - 10) = 0 (1.5 ពិន្ទុ)
បង្រួមបាន -6x - 6y + 20 = 0 នាំឱ្យសមីការអ័ក្សរ៉ាឌីកាល់ 3x + 3y - 10 = 0 នាំឱ្យ y = (10 - 3x)/3 (1 ពិន្ទុ)
ជំនួស y ចូលក្នុង C_1: x^2 + ((10-3x)/3)^2 = 10 នាំឱ្យ 9x^2 + 100 - 60x + 9x^2 = 90 (1 ពិន្ទុ)
បង្រួមបាន 18x^2 - 60x + 10 = 0 នាំឱ្យ 9x^2 - 30x + 5 = 0 (0.5 ពិន្ទុ)
ដោះស្រាយរក x = (15 ± 3*sqrt(20))/9 = (5 ± 2*sqrt(5))/3 និង y ត្រូវគ្នា (1 ពិន្ទុ)', 'សមីការរង្វង់', 'hard', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11245, 'ពីចំណុច \(P(4, 3)\) គេគូសបន្ទាត់ប៉ះពីរទៅកាន់រង្វង់ \(x^2 + y^2 = 5\)។
ក. បង្ហាញថាចំណុច \(P\) នៅក្រៅរង្វង់។
ខ. សរសេរសមីការបន្ទាត់ប៉ះទាំងពីរដែលគូសចេញពី \(P\) ទៅកាន់រង្វង់នោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ពិនិត្យ OP^2 = 4^2 + 3^2 = 25 > R^2 = 5 នាំឱ្យ P នៅក្រៅរង្វង់ (1 ពិន្ទុ)
តាងសមីការបន្ទាត់ប៉ះកាត់ P: y - 3 = m(x - 4) នាំឱ្យ mx - y + (3 - 4m) = 0 (1 ពិន្ទុ)
លក្ខខណ្ឌប៉ះ: |3 - 4m| / sqrt(m^2 + 1) = sqrt(5) នាំឱ្យ (3 - 4m)^2 = 5(m^2 + 1) (1 ពិន្ទុ)
ពន្លាត: 9 - 24m + 16m^2 = 5m^2 + 5 នាំឱ្យ 11m^2 - 24m + 4 = 0 (1 ពិន្ទុ)
ដោះស្រាយបាន m = 2 ឬ m = 2/11 នាំឱ្យបន្ទាត់ប៉ះទាំងពីរគឺ 2x - y - 5 = 0 និង 2x - 11y + 25 = 0 (1 ពិន្ទុ)', 'សមីការរង្វង់', 'hard', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11246, 'ប្រព័ន្ធធារាសាស្ត្រកសិកម្មដំឡើងក្បាលបាញ់ទឹកវិលមួយកន្លែងនៅចំណុច \(I(10, 20)\) (គិតជាម៉ែត្រ)។ ក្បាលបាញ់ទឹកនេះអាចបាញ់បានចម្ងាយអតិបរមា \(15\\text{ m}\)។
ក. សរសេរសមីការព្រំប្រទល់រង្វង់នៃផ្ទៃដីដែលទទូលបានទឹកស្រោចស្រព។
ខ. គណនាផ្ទៃក្រឡាសរុបនៃចម្ការដែលទទូលបានទឹកស្រោចស្រព (យក \(\pi \approx 3.14\))។
គ. ដើមស្វាយមួយដើមដាំនៅទីតាំង \(M(22, 11)\)។ តើដើមស្វាយនេះអាចទទូលទឹកពីក្បាលបាញ់នេះបានដែរឬទេ?', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរសមីការរង្វង់ព្រំប្រទល់: (x - 10)^2 + (y - 20)^2 = 15^2 = 225 (1.5 ពិន្ទុ)
គណនាផ្ទៃក្រឡាស្រោចស្រព S = pi * R^2 = 3.14 * 225 = 706.5 ម៉ែត្រការេ (1.5 ពិន្ទុ)
គណនាចម្ងាយពីក្បាលបាញ់ទៅដើមស្វាយ: IM^2 = (22 - 10)^2 + (11 - 20)^2 = 12^2 + (-9)^2 = 144 + 81 = 225 (1 ពិន្ទុ)
សន្និដ្ឋានថា IM = 15m = R នាំឱ្យដើមស្វាយស្ថិតនៅលើគែមរង្វង់ល្មម ដូច្នេះទទួលបានទឹកស្រោចស្រព (1 ពិន្ទុ)', 'សមីការរង្វង់', 'pisa', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11247, 'ស្ថានីយ៍រ៉ាដាកងទ័ពជើងទឹកមួយស្ថិតនៅកោះ \(O(0, 0)\) មានដែនរ៉ាដាកំណត់ដោយរង្វង់ \(x^2 + y^2 \le 2\\,500\) (គិតជាគីឡូម៉ែត្រ)។
ក. កំណត់កាំគ្របដណ្តប់អតិបរមានៃរ៉ាដានេះ។
ខ. នាវាចម្បាំងមួយកំពុងល្បាតតាមខ្សែបន្ទាត់ត្រង់ \(3x + 4y - 200 = 0\)។ គណនាចម្ងាយកាត់កែងជិតបំផុតពីស្ថានីយ៍រ៉ាដាទៅគន្លងនាវា។
គ. តើនាវានោះអាចឆ្លងកាត់ចូលក្នុងដែនរ៉ាដាបានដែរឬទេ?', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កាំរ៉ាដា R = sqrt(2,500) = 50 km (1 ពិន្ទុ)
គណនាចម្ងាយជិតបំផុត d = |3(0) + 4(0) - 200| / sqrt(3^2 + 4^2) = 200 / 5 = 40 km (1.5 ពិន្ទុ)
ប្រៀបធៀបចម្ងាយ d = 40 km ជាមួយកាំ R = 50 km (1 ពិន្ទុ)
សន្និដ្ឋានថាដោយសារ d < R (40 < 50) នាវានឹងកាត់ចូលក្នុងដែនរ៉ាដាពិតមែន (1.5 ពិន្ទុ)', 'សមីការរង្វង់', 'pisa', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11248, 'វិស្វកររចនាប្លង់អាងចិញ្ចឹមត្រីរាងជារង្វង់មូលមួយ ដែលមានអង្កត់ផ្ចិតតភ្ជាប់ពីបង្គោល \(A(2, 4)\) ទៅបង្គោល \(B(8, 12)\) (គិតជាម៉ែត្រ)។
ក. រកកូអរដោនេនៃចំណុចកណ្តាល (ផ្ចិត) និងប្រវែងកាំនៃអាងត្រីនោះ។
ខ. សរសេរសមីការព្រំប្រទល់អាងត្រី។
គ. គណនាបរិមាត្ររបងដែកដែលត្រូវព័ទ្ធជុំវិញអាងត្រីនេះ (យក \(\pi \approx 3.14\))។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផ្ចិត I: x_I = (2+8)/2 = 5, y_I = (4+12)/2 = 8 នាំឱ្យ I(5, 8) (1 ពិន្ទុ)
គណនាអង្កត់ផ្ចិត AB = sqrt((8-2)^2 + (12-4)^2) = sqrt(36 + 64) = 10m នាំឱ្យកាំ R = 5m (1.5 ពិន្ទុ)
សរសេរសមីការរង្វង់ (x - 5)^2 + (y - 8)^2 = 25 (1 ពិន្ទុ)
គណនាបរិមាត្ររបង P = 2 * pi * R = 2 * 3.14 * 5 = 31.4 ម៉ែត្រ (1.5 ពិន្ទុ)', 'សមីការរង្វង់', 'pisa', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11249, 'បន្ទះឌីសឡាស៊ែរ (DVD) មួយមានរាងជារង្វង់រួមផ្ចិតពីរ។ រង្វង់ក្នុង (រន្ធកណ្តាល) មានសមីការ \(x^2 + y^2 = 2.25\) និងរង្វង់ក្រៅមានសមីការ \(x^2 + y^2 = 36\) (គិតជាសង់ទីម៉ែត្រការេ \(\\text{cm}^2\))។
ក. រកកាំនៃរង្វង់ក្នុង \(R_1\) និងកាំនៃរង្វង់ក្រៅ \(R_2\)។
ខ. គណនាផ្ទៃក្រឡាផ្ទុកទិន្នន័យនៃបន្ទះឌីស (ផ្ទៃចន្លោះរង្វង់ទាំងពីរ ឬផ្ទៃក្រវ៉ាត់កង) ជាអនុគមន៍នៃ \(\pi\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាញកាំរង្វង់ក្នុង R_1 = sqrt(2.25) = 1.5 cm (1.5 ពិន្ទុ)
ទាញកាំរង្វង់ក្រៅ R_2 = sqrt(36) = 6 cm (1.5 ពិន្ទុ)
រូបមន្តផ្ទៃក្រវ៉ាត់កង S = pi * (R_2^2 - R_1^2) (1 ពិន្ទុ)
គណនា S = pi * (36 - 2.25) = 33.75*pi cm^2 ≈ 105.98 cm^2 (1 ពិន្ទុ)', 'សមីការរង្វង់', 'pisa', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11250, 'ក្រុមហ៊ុនទូរគមនាគមន៍គ្រោងដំឡើងអង់តែនបញ្ជូនសញ្ញា 5G ថ្មីមួយនៅចំណុច \(P(x_0, y_0)\) លើផ្លូវជាតិ \(y = 2\) ដើម្បីឱ្យដែនគ្របដណ្តប់របស់វាប៉ះនឹងផ្លូវរថភ្លើងរាងជារង្វង់ \(x^2 + y^2 = 16\) ត្រង់ចំណុចមួយ។
ក. កំណត់កាំនៃផ្លូវរថភ្លើងរាងរង្វង់នោះ។
ខ. បើអង់តែនថ្មីមានកាំគ្របដណ្តប់ \(R = 6\\text{ km}\) រកចម្ងាយពីផ្ចិតរង្វង់រថភ្លើង \(O(0, 0)\) ទៅកាន់អង់តែន \(P\) ដើម្បីឱ្យរង្វង់ទាំងពីរប៉ះក្រៅគ្នា។
គ. រកកូអរដោនេនៃទីតាំងអង់តែន \(P\) លើផ្លូវជាតិ \(y = 2\) (យក \(x_0 > 0\))។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កាំរង្វង់រថភ្លើង R_1 = sqrt(16) = 4 km (1 ពិន្ទុ)
លក្ខខណ្ឌប៉ះក្រៅ: ចម្ងាយ OP = R_1 + R_2 = 4 + 6 = 10 km (1.5 ពិន្ទុ)
សរសេរសមីការចម្ងាយ OP^2 = x_0^2 + 2^2 = 10^2 = 100 (1 ពិន្ទុ)
ដោះស្រាយ x_0^2 = 96 នាំឱ្យ x_0 = sqrt(96) = 4*sqrt(6) ≈ 9.8 km (1 ពិន្ទុ)
សន្និដ្ឋានទីតាំងអង់តែន P(4*sqrt(6), 2) (0.5 ពិន្ទុ)', 'សមីការរង្វង់', 'pisa', 0, '10', 'សមីការរង្វង់', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
