INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11305, 'តាមរូបភាព វិសមីការតឹងរ៉ឹង \(2x - y > 2\) មានបន្ទាត់ព្រំប្រទល់ជា៖', 'g10-9ad893243e.svg', '["បន្ទាត់ព្រំប្រទល់ពីរ", "បន្ទាត់កោង", "បន្ទាត់ជាប់ (Solid line)", "បន្ទាត់ដាច់ៗ (Dashed line)"]', 3, NULL, 1, 'mcq', 'សញ្ញា \(>\) ឬ \(<\) ត្រូវគូសបន្ទាត់ដាច់ៗ ព្រោះចំណុចលើបន្ទាត់មិនរាប់បញ្ចូលក្នុងសំណុំចម្លើយទេ។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'easy', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11306, 'ប្រសិនបើតំបន់ដំណោះស្រាយនៃប្រព័ន្ធវិសមីការពីរគ្មានចំណុចរួមទាល់តែសោះ នោះប្រព័ន្ធមានសំណុំចម្លើយជា៖', NULL, '["\\(S = \\emptyset \\quad (\\text{សំណុំទទេ})\\)", "\\(S = \\mathbb{R}^2\\)", "ចំណុចមួយគត់", "បន្ទាត់ត្រង់មួយ"]', 0, NULL, 1, 'mcq', 'គ្មានចំណុចរួម នាំឱ្យសំណុំចម្លើយជាសំណុំទទេ \(\emptyset\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'easy', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11307, 'ចំណុចណាជាចម្លើយនៃវិសមីការ \(x + 2y \le 6\)?', NULL, '["\\((0, 4)\\)", "\\((1, 2)\\)", "\\((5, 1)\\)", "\\((4, 2)\\)"]', 1, NULL, 1, 'mcq', 'ជំនួស \((1, 2)\) ៖ \(1 + 2(2) = 5 \le 6\) ពិត។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'easy', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11308, 'តើគល់កូអរដោនេ \(O(0, 0)\) ជាចម្លើយនៃវិសមីការណា?', NULL, '["\\(3x + 2y + 5 < 0\\)", "\\(2x - 3y + 6 \\ge 0\\)", "\\(y - 2x > 3\\)", "\\(x + y - 4 > 0\\)"]', 1, NULL, 1, 'mcq', '\(2(0) - 3(0) + 6 = 6 \ge 0\) ពិត។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'easy', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11309, 'វិសមីការ \(x \ge 0\) និង \(y \ge 0\) កំណត់តំបន់ណាលើប្លង់កូអរដោនេ?', NULL, '["កាដ្រង់ទី ៣", "កាដ្រង់ទី ៤", "កាដ្រង់ទី ២", "កាដ្រង់ទី ១ (Quadrant I)"]', 3, NULL, 1, 'mcq', '\(x \ge 0\) និង \(y \ge 0\) ជាកាដ្រង់ទី ១ (អាប់ស៊ីសនិងអ័រដោនេវិជ្ជមាន)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'easy', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11310, 'តំបន់ដំណោះស្រាយនៃវិសមីការ \(y \ge 3\) គឺជាកន្លះប្លង់ដែលស្ថិតនៅ៖', NULL, '["ខាងស្តាំបន្ទាត់ឈរ x = 3", "ខាងលើបន្ទាត់ដេក y = 3 (រួមទាំងបន្ទាត់ផង)", "ខាងឆ្វេងបន្ទាត់ឈរ x = 3", "ខាងក្រោមបន្ទាត់ដេក y = 3"]', 1, NULL, 1, 'mcq', '\(y \ge 3\) ជាបណ្តុំចំណុចដែលមានអ័រដោនេធំជាងឬស្មើ 3 ពោលគឺផ្នែកខាងលើបន្ទាត់ដេក \(y = 3\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'easy', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11311, 'រកកូអរដោនេនៃកំពូលប្រសព្វរវាងបន្ទាត់ព្រំប្រទល់ពីរ \(x + y = 6\) និង \(2x + y = 8\)៖', NULL, '["\\((1, 5)\\)", "\\((2, 4)\\)", "\\((4, 2)\\)", "\\((3, 3)\\)"]', 1, NULL, 2, 'mcq', 'ដកសមីការទាំងពីរ ៖ \((2x + y) - (x + y) = 8 - 6 \implies x = 2 \implies y = 6 - 2 = 4 \implies (2, 4)\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11312, 'រកតម្លៃអតិបរមានៃ \(Z = 3x + 2y\) លើដែនពហុកោណដែលមានកំពូល \(O(0, 0), A(4, 0), B(2, 4), C(0, 5)\)៖', NULL, '["\\(10\\)", "\\(12\\)", "\\(15\\)", "\\(14\\)"]', 3, NULL, 2, 'mcq', 'គណនាតម្លៃ Z ត្រង់កំពូលនីមួយៗ ៖ \(Z(O)=0, Z(A)=3(4)+0=12, Z(B)=3(2)+2(4)=14, Z(C)=0+2(5)=10 \implies \max Z = 14\) (ត្រង់ B)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11313, 'តើចំណុចណាស្ថិតក្នុងដែនចម្លើយនៃប្រព័ន្ធ \(\begin{cases} x + y > 3 \\ 2x - y < 4 \end{cases}\)?', NULL, '["\\((1, 1)\\)", "\\((4, 1)\\)", "\\((2, 3)\\)", "\\((0, 2)\\)"]', 2, NULL, 2, 'mcq', '\((2, 3) \implies 2+3=5>3\) និង \(2(2)-3=1<4\) ផ្ទៀងផ្ទាត់ទាំងពីរ។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11314, 'ចំណុចណាស្ថិតក្នុងដែនចម្លើយរួមនៃប្រព័ន្ធ \(\begin{cases} x^2 + y^2 \le 25 \\ y \ge x + 1 \end{cases}\)?', NULL, '["\\((1, 3)\\)", "\\((3, 1)\\)", "\\((4, 4)\\)", "\\((0, 0)\\)"]', 0, NULL, 2, 'mcq', 'ជំនួស \((1, 3)\) ៖ \(1^2 + 3^2 = 10 \le 25\) និង \(3 \ge 1 + 1 = 2\) ពិត។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11315, 'ដែនចម្លើយនៃប្រព័ន្ធវិសមីការ \(\begin{cases} x \ge 0, \ y \ge 0 \\ x + y \le 5 \end{cases}\) មានរាងជា៖', NULL, '["ចតុកោណកែង", "ត្រីកោណសម័ង្ស", "ត្រីកោណកែងសមបាត", "ការេ"]', 2, NULL, 2, 'mcq', 'កំពូលទាំងបីគឺ \((0, 0), (5, 0), (0, 5)\) បង្កើតបានជាត្រីកោណកែងសមបាតនៅគល់កូអរដោនេ។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11316, 'រកតម្លៃអប្បបរមានៃ \(C = 2x + 5y\) លើដែនពហុកោណដែលមានកំពូល \(A(1, 4), B(3, 1), C(5, 2)\)៖', NULL, '["\\(20\\)", "\\(13\\)", "\\(11\\)", "\\(22\\)"]', 2, NULL, 2, 'mcq', '\(C(A) = 2(1) + 5(4) = 22; \ C(B) = 2(3) + 5(1) = 11; \ C(C) = 2(5) + 5(2) = 20 \implies \min C = 11\) (ត្រង់ B)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11317, 'ដើម្បីកំណត់ថាកន្លះប្លង់ណាជាចម្លើយនៃ \(3x - 2y \le 6\) គេជ្រើសរើសចំណុចសាកល្បង \(O(0, 0)\)។ លទ្ធផលនៃការសាកល្បងគឺ៖', NULL, '["\\(0 \\le 6 \\text{ (ពិត ដូច្នេះកន្លះប្លង់ដែលមាន O ជាចម្លើយ)}\\)", "\\(0 > 6 \\text{ (ពិត)}\\)", "\\(0 \\le 6 \\text{ (មិនពិត)}\\)", "មិនអាចសាកល្បងជាមួយគល់កូអរដោនេ O បានទេ"]', 0, NULL, 2, 'mcq', '\(3(0) - 2(0) = 0 \le 6\) ពិត ដូច្នេះកន្លះប្លង់ដែលមាន O(0,0) ជាតំបន់ចម្លើយ។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11318, 'វិសមីការ \(x^2 + y^2 > 16\) តាងឱ្យ៖', NULL, '["ផ្ទៃខាងក្នុងរង្វង់កាំ 4", "ផ្ទៃរង្វង់កាំ 16", "ខ្សែរង្វង់កាំ 4", "ផ្ទៃខាងក្រៅនៃរង្វង់ផ្ចិត O កាំ R = 4 (មិនរាប់ខ្សែរង្វង់)"]', 3, NULL, 2, 'mcq', 'សញ្ញា \(>\) តំណាងឱ្យផ្ទៃក្រៅសុទ្ធនៃរង្វង់ផ្ចិតគល់កូអរដោនេកាំ 4។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11319, 'ផ្ទៃក្រឡានៃដែនចម្លើយដែលកំណត់ដោយ \(x \ge 0, \ y \ge 0, \ 2x + 3y \le 12\) ស្មើនឹង៖', NULL, '["\\(24\\)", "\\(6\\)", "\\(12\\)", "\\(18\\)"]', 2, NULL, 2, 'mcq', 'ប្រសព្វអ័ក្ស \((6, 0)\) និង \((0, 4)\)។ \(S = \dfrac{1}{2} \times 6 \times 4 = 12\) ឯកតាផ្ទៃ។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11320, 'អនុគមន៍ចំណេញ \(P = 5x + 4y\) លើដែនចម្លើយដែលមានកំពូល \((0, 0), (6, 0), (4, 3), (0, 5)\) មានតម្លៃអតិបរមាស្មើនឹង៖', NULL, '["\\(35\\)", "\\(30\\)", "\\(20\\)", "\\(32\\)"]', 3, NULL, 2, 'mcq', '\(P(0, 0)=0; \ P(6, 0)=30; \ P(4, 3)=5(4)+4(3)=32; \ P(0, 5)=20 \implies \max P = 32\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11321, 'ប្រព័ន្ធវិសមីការ \(\begin{cases} y \ge x + 2 \\ y \le x - 1 \end{cases}\) មានសំណុំចម្លើយជា៖', NULL, '["\\(S = \\mathbb{R}^2\\)", "\\(S = \\emptyset\\)", "បន្ទាត់មួយ", "តំបន់រវាងបន្ទាត់ស្របគ្នាទាំងពីរ"]', 1, NULL, 2, 'mcq', 'បន្ទាត់ទាំងពីរស្របគ្នា ហើយកន្លះប្លង់ចម្លើយបែរខ្នងដាក់គ្នា (មិនប្រសព្វគ្នា) នាំឱ្យគ្មានចម្លើយ។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11322, 'ដែនចម្លើយនៃ \(x \ge 0, \ y \ge 0, \ x \le 4, \ y \le 3\) មានផ្ទៃក្រឡាស្មើនឹង៖', NULL, '["\\(7\\)", "\\(12\\)", "\\(24\\)", "\\(14\\)"]', 1, NULL, 2, 'mcq', 'ដែននេះជារាងចតុកោណកែងដែលមានវិមាត្រ 4 និង 3 នាំឱ្យ \(S = 4 \times 3 = 12\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11323, 'ចំនួនកំពូលនៃពហុកោណដែនចម្លើយនៃប្រព័ន្ធ \(x \ge 0, \ y \ge 0, \ x + y \le 6, \ x \le 4\) គឺ៖', NULL, '["\\(3\\)", "\\(6\\)", "\\(4\\)", "\\(5\\)"]', 2, NULL, 2, 'mcq', 'កំពូលទាំង 4 គឺ \((0, 0), (4, 0), (4, 2), (0, 6)\) ជាចតុកោណព្នាយកែង។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11324, 'ប្រព័ន្ធវិសមីការ \(\begin{cases} -2 \le x \le 3 \\ 1 \le y \le 5 \end{cases}\) កំណត់បានផ្ទៃក្រឡាស្មើនឹង៖', NULL, '["\\(25\\)", "\\(10\\)", "\\(15\\)", "\\(20\\)"]', 3, NULL, 2, 'mcq', 'បណ្តោយ \(3 - (-2) = 5\), ទទឹង \(5 - 1 = 4 \implies S = 5 \times 4 = 20\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11325, 'រកតម្លៃអតិបរមានៃ \(Z = 4x + 3y\) ក្រោមលក្ខខណ្ឌ \(x \ge 0, y \ge 0, 2x + y \le 10, x + 2y \le 8\)៖', NULL, '["\\(24\\)", "\\(22\\)", "\\(18\\)", "\\(20\\)"]', 1, NULL, 3, 'mcq', 'ប្រសព្វព្រំប្រទល់ ៖ \(2(2x+y) - (x+2y) = 20 - 8 \implies 3x = 12 \implies x = 4, y = 2\)។ កំពូល ៖ \((0, 0), (5, 0), (4, 2), (0, 4)\)។ \(Z(5, 0)=20; Z(4, 2)=4(4)+3(2)=22; Z(0, 4)=12 \implies \max Z = 22\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11326, 'ប្រព័ន្ធវិសមីការ \(\begin{cases} x + 2y \ge 4 \\ 2x + y \ge 5 \\ x \ge 0, y \ge 0 \end{cases}\) មានដែនចម្លើយមិនកម្រិត។ កំពូលនៃដែនចម្លើយនេះគឺ៖', NULL, '["\\((0, 0), (2, 1), (4, 0)\\)", "\\((0, 5), (2, 1), (4, 0)\\)", "\\((0, 4), (1, 2), (5, 0)\\)", "\\((0, 5), (3, 0), (1, 2)\\)"]', 1, NULL, 3, 'mcq', 'ប្រសព្វរវាង \(x + 2y = 4\) និង \(2x + y = 5\) គឺ \((2, 1)\)។ ប្រសព្វអ័ក្សគឺ \((0, 5)\) និង \((4, 0)\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11327, 'ផ្ទៃក្រឡានៃដែនចម្លើយដែលកំណត់ដោយ \(x^2 + y^2 \le 16\) និង \(y \ge |x|\) ស្មើនឹង៖', NULL, '["\\(4\\\\pi\\)", "\\(8\\\\pi\\)", "\\(2\\\\pi\\)", "\\(16\\\\pi\\)"]', 0, NULL, 3, 'mcq', 'មុំនៃតំបន់ \(y \ge |x|\) គឺពី \(45^\circ\) ដល់ \(135^\circ\) (មុំ \(90^\circ\)) ស្មើនឹង \(1/4\) នៃរង្វង់ ៖ \(S = \dfrac{1}{4}\pi (4^2) = 4\pi\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11328, 'រកតម្លៃអប្បបរមានៃ \(Z = 2x - y\) លើដែនចតុកោណកែងដែលមានកំពូល \((1, 1), (4, 1), (4, 5), (1, 5)\)៖', NULL, '["\\(1\\)", "\\(-3\\)", "\\(-5\\)", "\\(3\\)"]', 1, NULL, 3, 'mcq', '\(Z(1, 1)=1; Z(4, 1)=7; Z(4, 5)=3; Z(1, 5)=2(1)-5=-3 \implies \min Z = -3\) (ត្រង់កំពូល (1, 5))។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11329, 'បរិមាត្រនៃពហុកោណដែលជាដែនចម្លើយនៃ \(x \ge 0, y \ge 0, 3x + 4y \le 12\) គឺ៖', NULL, '["\\(12\\)", "\\(7\\)", "\\(14\\)", "\\(10\\)"]', 0, NULL, 3, 'mcq', 'កំពូលគឺ \((0, 0), (4, 0), (0, 3)\)។ ជ្រុងទាំងបីគឺ \(4, 3\) និងអ៊ីប៉ូតេនុស \(\sqrt{4^2+3^2}=5 \implies P = 4 + 3 + 5 = 12\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11330, 'ចំណុចប្រសព្វរវាងព្រំប្រទល់នៃវិសមីការ \(y \ge x^2\) និង \(y \le x + 2\) គឺ៖', NULL, '["\\((1, 1) \\text{ និង } (-2, 4)\\)", "\\((0, 0) \\text{ និង } (2, 2)\\)", "\\((-1, 1) \\text{ និង } (2, 4)\\)", "\\((-1, 2) \\text{ និង } (2, 3)\\)"]', 2, NULL, 3, 'mcq', '\(x^2 = x + 2 \implies x^2 - x - 2 = 0 \implies (x-2)(x+1) = 0 \implies x = 2 \ (y = 4)\) និង \(x = -1 \ (y = 1)\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11331, 'បើអនុគមន៍គោលដៅ \(Z = ax + by\) មានតម្លៃអតិបរមាស្មើគ្នាត្រង់កំពូលពីរផ្សេងគ្នានៃដែនចម្លើយប៉ូលីហ្គោន នោះ Z មានតម្លៃអតិបរមាត្រង់ណាទៀត?', NULL, '["ត្រង់គ្រប់ចំណុចទាំងអស់នៅលើអង្កត់តភ្ជាប់កំពូលទាំងពីរនោះ", "ត្រង់គល់កូអរដោនេ O", "ត្រង់គ្រប់ចំណុចក្នុងដែនពហុកោណ", "គ្មានចំណុចណាផ្សេងទៀតទេ"]', 0, NULL, 3, 'mcq', 'កាលណាតម្លៃបរមាកើតមានត្រង់កំពូលជាប់គ្នាពីរ នោះគ្រប់ចំណុចលើជ្រុងតភ្ជាប់កំពូលទាំងពីរក៏ជាចម្លើយអតិបរមាដែរ (ចម្លើយច្រើនរាប់មិនអស់)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11332, 'រោងចក្រកាត់ដេរសម្លៀកបំពាក់មួយផលិតអាវ \(x\) និងខោ \(y\) ក្នុងមួយថ្ងៃ។ ដោយសារកម្លាំងពលកម្មមានកំណត់ ផលបូកសរុបមិនអាចលើសពី 100 កំប្លេបានទេ (\(x + y \le 100\)) ហើយអាវត្រូវផលិតយ៉ាងហោចណាស់ 20 (\(x \ge 20\))។ តើគូផលិតកម្មណាអាចធ្វើទៅបាន?', NULL, '["\\(x = 15, y = 70\\)", "\\(x = 10, y = 80\\)", "\\(x = 30, y = 60\\)", "\\(x = 50, y = 60\\)"]', 2, NULL, 3, 'mcq', '\(x = 30 \ge 20\) និង \(30 + 60 = 90 \le 100\) ផ្ទៀងផ្ទាត់គ្រប់លក្ខខណ្ឌទាំងអស់។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11333, 'កសិករម្នាក់ដាំស្រូវលើដី \(x\) ហិកតា និងដាំពោតលើដី \(y\) ហិកតា។ ដីសរុបមានយ៉ាងច្រើន \(12\\text{ ha}\) (\(x + y \le 12\))។ ស្រូវផ្តល់ប្រាក់ចំណេញ \(400\) ដុល្លារ/ha និងពោត \(300\) ដុល្លារ/ha (\(P = 400x + 300y\))។ ដើម្បីចំណេញច្រើនបំផុត គាត់គួរដាំ៖', NULL, '["ដាំពោតទាំងអស់ 12 ហិកតា (ចំណេញ 3,600 ដុល្លារ)", "ដាំស្រូវ 6 ha និងពោត 6 ha", "ដាំស្រូវ 4 ha និងពោត 8 ha", "ដាំស្រូវទាំងអស់ 12 ហិកតា (ចំណេញ 4,800 ដុល្លារ)"]', 3, NULL, 3, 'mcq', '\(P(12, 0) = 400(12) = 4\,800\) ដុល្លារ ជាតម្លៃអតិបរមា ព្រោះស្រូវផ្តល់ចំណេញក្នុង ១ ហិកតាខ្ពស់ជាងពោត។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11334, 'របបអាហាររូបត្ថម្ភប្រចាំថ្ងៃរបស់សិស្សម្នាក់ត្រូវការជាតិប្រូតេអ៊ីនយ៉ាងតិច \(50\\text{ g}\) និងជាតិដែកយ៉ាងតិច \(10\\text{ mg}\)។ បើចំណីអាហារប្រភេទ A ផ្តល់ប្រូតេអ៊ីន 10g និងជាតិដែក 1mg ឯប្រភេទ B ផ្តល់ប្រូតេអ៊ីន 5g និងជាតិដែក 2mg នោះប្រព័ន្ធវិសមីការតម្រូវការអាហារគឺ៖', NULL, '["\\(\\begin{cases} 10x + 5y \\le 50 \\\\ x + 2y \\le 10 \\end{cases}\\)", "\\(\\begin{cases} 10x + 5y \\ge 50 \\\\ x + 2y \\ge 10 \\\\ x \\ge 0, y \\ge 0 \\end{cases}\\)", "\\(\\begin{cases} 10x + y \\ge 50 \\\\ 5x + 2y \\ge 10 \\end{cases}\\)", "\\(\\begin{cases} x + y \\ge 60 \\\\ x \\ge 0, y \\ge 0 \\end{cases}\\)"]', 1, NULL, 3, 'mcq', 'ប្រូតេអ៊ីនយ៉ាងតិច 50g នាំឱ្យ \(10x + 5y \ge 50\); ជាតិដែកយ៉ាងតិច 10mg នាំឱ្យ \(x + 2y \ge 10\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11335, 'ក្រុមហ៊ុនដឹកជញ្ជូនប្រើប្រាស់ឡានធុនតូច \(x\) គ្រឿង និងឡានធុនធំ \(y\) គ្រឿង។ ឡានតូចដឹកបាន 2 តោន ឡានធំដឹកបាន 5 តោន។ គេត្រូវការដឹកទំនិញយ៉ាងតិច 30 តោន ក្នុងមួយជើង។ វិសមីការតំណាងសមត្ថភាពដឹកជញ្ជូនគឺ៖', NULL, '["\\(2x + 5y \\ge 30\\)", "\\(x + y \\ge 30\\)", "\\(2x + 5y \\le 30\\)", "\\(5x + 2y \\ge 30\\)"]', 0, NULL, 3, 'mcq', 'ទម្ងន់ដឹកសរុបគឺ \(2x + 5y\) ហើយតម្រូវការយ៉ាងតិច 30 តោន គឺ \(2x + 5y \ge 30\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11336, 'ហាងនំប៉័ងមួយមានម្សៅសរុប \(18\\text{ kg}\)។ នំប្រភេទទីមួយត្រូវការម្សៅ \(0.3\\text{ kg}\) និងនំទីពីរត្រូវការ \(0.2\\text{ kg}\)។ បើ \(x\) និង \(y\) ជាចំនួននំទាំងពីរប្រភេទដែលត្រូវធ្វើ នោះវិសមីការកំណត់បរិមាណម្សៅគឺ៖', NULL, '["\\(0.3x + 0.2y \\le 18 \\quad (3x + 2y \\le 180)\\)", "\\(0.3x + 0.2y \\ge 18\\)", "\\(0.2x + 0.3y \\le 18\\)", "\\(x + y \\le 18\\)"]', 0, NULL, 3, 'mcq', 'បរិមាណម្សៅសរុបមិនអាចលើសពី \(18\\text{ kg}\) នាំឱ្យ \(0.3x + 0.2y \le 18\)។', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 1, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11337, 'ចូរដោះស្រាយវិសមីការ \(2x + y - 4 \le 0\) តាមវិធីក្រាប។
ក. រកកូអរដោនេនៃចំណុចប្រសព្វរវាងបន្ទាត់ព្រំប្រទល់ \(2x + y - 4 = 0\) ជាមួយអ័ក្សកូអរដោនេទាំងពីរ។
ខ. ជ្រើសរើសចំណុចសាកល្បង \(O(0, 0)\) ដើម្បីកំណត់កន្លះប្លង់ដំណោះស្រាយ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ប្រសព្វនឹង Ox (y=0): 2x - 4 = 0 នាំឱ្យ x = 2 នាំឱ្យ A(2, 0) (1.5 ពិន្ទុ)
កំណត់ប្រសព្វនឹង Oy (x=0): y - 4 = 0 នាំឱ្យ y = 4 នាំឱ្យ B(0, 4) (1.5 ពិន្ទុ)
ជំនួស O(0, 0) ចូលក្នុងវិសមីការ: 2(0) + 0 - 4 = -4 <= 0 (ពិត) (1 ពិន្ទុ)
សន្និដ្ឋានថាកន្លះប្លង់ដែលមាន O(0, 0) រួមទាំងបន្ទាត់ព្រំប្រទល់ 2x+y-4=0 ជាសំណុំចម្លើយ (1 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'easy', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11338, 'ដោះស្រាយប្រព័ន្ធវិសមីការតាមក្រាប ៖ \(\begin{cases} x + y \le 5 \\ x - y \le 1 \\ x \ge 0, \ y \ge 0 \end{cases}\)។
ក. រកកូអរដោនេនៃចំណុចប្រសព្វរវាងបន្ទាត់ទាំងពីរ \(x + y = 5\) និង \(x - y = 1\)។
ខ. កំណត់កូអរដោនេនៃកំពូលទាំងអស់នៃពហុកោណដែលជាដែនចម្លើយ។', NULL, '[]', 0, NULL, 5, 'writing', 'បូកសមីការទាំងពីរ: 2x = 6 នាំឱ្យ x = 3 និង y = 5 - 3 = 2 នាំឱ្យប្រសព្វ (3, 2) (1.5 ពិន្ទុ)
រកប្រសព្វនឹងអ័ក្សកូអរដោនេ: (0, 0), (1, 0) ពី x-y=1, (0, 5) ពី x+y=5 (1.5 ពិន្ទុ)
ផ្ទៀងផ្ទាត់តំបន់ដំណោះស្រាយក្នុងកាដ្រង់ទី ១ ជាប់គល់ O(0, 0) (1 ពិន្ទុ)
សន្និដ្ឋានកំពូលទាំង 4 នៃដែនចម្លើយគឺ (0, 0), (1, 0), (3, 2), (0, 5) (1 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11339, 'រកតម្លៃអតិបរមានិងអប្បបរមានៃអនុគមន៍ \(Z = 4x + 5y\) លើដែនពហុកោណដែលកំណត់ដោយកំពូល \(O(0, 0), A(4, 0), B(3, 3), C(0, 4)\)។
ក. គណនាតម្លៃនៃ \(Z\) ត្រង់កំពូលនីមួយៗទាំងបួន។
ខ. កំណត់តម្លៃអតិបរមា និងតម្លៃអប្បបរមានៃ \(Z\) ព្រមទាំងបញ្ជាក់ចំណុចដែលកើតមាន។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា Z(O) = 4(0) + 5(0) = 0 (1 ពិន្ទុ)
គណនា Z(A) = 4(4) + 5(0) = 16 (1 ពិន្ទុ)
គណនា Z(B) = 4(3) + 5(3) = 12 + 15 = 27 (1 ពិន្ទុ)
គណនា Z(C) = 4(0) + 5(4) = 20 (1 ពិន្ទុ)
សន្និដ្ឋានថា max Z = 27 (ត្រង់ B(3, 3)) និង min Z = 0 (ត្រង់ O(0, 0)) (1 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11340, 'ដោះស្រាយប្រព័ន្ធវិសមីការមិនលីនេអ៊ែរតាមក្រាប ៖ \(\begin{cases} x^2 + y^2 \le 16 \\ y \ge 2 \end{cases}\)។
ក. ពិពណ៌នាអំពីរូបរាងនៃតំបន់ដំណោះស្រាយក្នុងប្លង់កូអរដោនេ។
ខ. រកកូអរដោនេនៃចំណុចប្រសព្វរវាងបន្ទាត់ \(y = 2\) និងរង្វង់ \(x^2 + y^2 = 16\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ x^2 + y^2 <= 16 ជាផ្ទៃខាងក្នុងរង្វង់ផ្ចិត O(0, 0) កាំ R = 4 (1.5 ពិន្ទុ)
កំណត់ y >= 2 ជាកន្លះប្លង់ខាងលើបន្ទាត់ដេក y = 2 (1 ពិន្ទុ)
សន្និដ្ឋានថាដែនចម្លើយជាកំណាត់រង្វង់ (Circular segment) ផ្នែកខាងលើនៃបន្ទាត់ y = 2 (1 ពិន្ទុ)
ជំនួស y = 2 ចូលសមីការរង្វង់: x^2 + 4 = 16 នាំឱ្យ x^2 = 12 នាំឱ្យ x = ±2*sqrt(3) (1 ពិន្ទុ)
ទាញបានចំណុចប្រសព្វទាំងពីរគឺ (-2*sqrt(3), 2) និង (2*sqrt(3), 2) (0.5 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11341, 'គេឱ្យប្រព័ន្ធវិសមីការ \(\begin{cases} 2x + 3y \le 12 \\ x \ge 1 \\ y \ge 1 \end{cases}\)។
ក. បង្ហាញថាដែនចម្លើយនៃប្រព័ន្ធនេះជារាងត្រីកោណ។
ខ. រកកូអរដោនេនៃកំពូលទាំងបីនៃត្រីកោណនោះ។
គ. គណនាផ្ទៃក្រឡានៃត្រីកោណដែនចម្លើយ។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស x = 1 និង y = 1 រកកំពូលទីមួយ A(1, 1) (1 ពិន្ទុ)
ប្រសព្វ x = 1 ជាមួយ 2x + 3y = 12 នាំឱ្យ 3y = 10 នាំឱ្យ y = 10/3 នាំឱ្យ B(1, 10/3) (1 ពិន្ទុ)
ប្រសព្វ y = 1 ជាមួយ 2x + 3y = 12 នាំឱ្យ 2x = 9 នាំឱ្យ x = 4.5 នាំឱ្យ C(4.5, 1) (1 ពិន្ទុ)
គណនាជ្រុងកែងឈរ AB = 10/3 - 1 = 7/3 និងជ្រុងដេក AC = 4.5 - 1 = 3.5 = 7/2 (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡា S = (1/2) * (7/2) * (7/3) = 49/12 ≈ 4.08 ឯកតាផ្ទៃ (1 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'medium', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11342, 'ដោះស្រាយចំណោទកម្មវិធីលីនេអ៊ែរ ៖ រកតម្លៃអប្បបរមានៃ \(C = 3x + 4y\) ក្រោមលក្ខខណ្ឌ ៖
\(\begin{cases} x + y \ge 4 \\ 2x + y \ge 5 \\ x \ge 0, \ y \ge 0 \end{cases}\)។
ក. រកកូអរដោនេនៃកំពូលទាំងអស់នៃដែនចម្លើយមិនកម្រិតនេះ។
ខ. គណនាតម្លៃនៃ \(C\) ត្រង់កំពូលនីមួយៗ រួចទាញរកតម្លៃអប្បបរមានៃ \(C\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ប្រសព្វអ័ក្ស Oy (x = 0): y >= 4 និង y >= 5 នាំឱ្យកំពូលទីមួយ A(0, 5) (1 ពិន្ទុ)
ប្រសព្វបន្ទាត់ទាំងពីរ: (2x + y) - (x + y) = 5 - 4 នាំឱ្យ x = 1, y = 3 នាំឱ្យ B(1, 3) (1.5 ពិន្ទុ)
ប្រសព្វអ័ក្ស Ox (y = 0): x >= 4 និង 2x >= 5 នាំឱ្យកំពូលទីបី C(4, 0) (1 ពិន្ទុ)
គណនា C(A) = 3(0) + 4(5) = 20; C(B) = 3(1) + 4(3) = 15; C(C) = 3(4) + 4(0) = 12 (1 ពិន្ទុ)
សន្និដ្ឋានថា min C = 12 កើតមានត្រង់ចំណុច C(4, 0) (0.5 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11343, 'គេឱ្យប្រព័ន្ធវិសមីការ \(\begin{cases} x - y \le 2 \\ x + 2y \le 8 \\ x \ge 0, \ y \ge 0 \end{cases}\)។
ក. សង់ដែនចម្លើយនៃប្រព័ន្ធវិសមីការនេះលើប្លង់កូអរដោនេ។
ខ. រកកូអរដោនេនៃកំពូលទាំង 4 នៃពហុកោណដែនចម្លើយ។
គ. គណនាផ្ទៃក្រឡានៃពហុកោណដែនចម្លើយនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'រកប្រសព្វបន្ទាត់ទាំងពីរ: ដកសមីការបាន -3y = -6 នាំឱ្យ y = 2, x = 4 នាំឱ្យកំពូល (4, 2) (1 ពិន្ទុ)
កំណត់កំពូលទាំងបួនគឺ O(0, 0), A(2, 0), B(4, 2), C(0, 4) (1 ពិន្ទុ)
បំបែកពហុកោណ OABC ជាពីរត្រីកោណ OAC និង ABC ឬប្រើរូបមន្ត Shoelace (1 ពិន្ទុ)
អនុវត្ត Shoelace: 2S = |0 + 2(2) + 4(4) + 0 - (0 + 0 + 2(0) + 4(0))| = |4 + 16| = 20 (1 ពិន្ទុ)
ទាញបានផ្ទៃក្រឡា S = 20 / 2 = 10 ឯកតាផ្ទៃ (1 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11344, 'ដោះស្រាយប្រព័ន្ធវិសមីការ \(\begin{cases} x^2 + y^2 \le 25 \\ x + y \ge 5 \end{cases}\) តាមវិធីក្រាប។
ក. រកចំណុចប្រសព្វរវាងបន្ទាត់ \(x + y = 5\) និងរង្វង់ \(x^2 + y^2 = 25\)។
ខ. គណនាផ្ទៃក្រឡានៃតំបន់ដំណោះស្រាយ (យក \(\pi \approx 3.14\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស y = 5 - x ចូលរង្វង់: x^2 + (5-x)^2 = 25 នាំឱ្យ 2x^2 - 10x = 0 នាំឱ្យ 2x(x - 5) = 0 (1 ពិន្ទុ)
ទាញបានប្រសព្វពីរគឺ A(5, 0) និង B(0, 5) (1 ពិន្ទុ)
សម្គាល់ថាតំបន់ចម្លើយជាកំណាត់រង្វង់ក្នុងកាដ្រង់ទី ១ ចន្លោះធ្នូ AB និងអង្កត់ធ្នូ AB (1 ពិន្ទុ)
គណនាផ្ទៃចំរៀករង្វង់មុំ 90 ដឺក្រេ: S_sector = (1/4) * pi * 5^2 = 25pi / 4 ≈ 19.625 (1 ពិន្ទុ)
ដកផ្ទៃត្រីកោណកែង OAB: S_tri = (1/2)*5*5 = 12.5 នាំឱ្យ S = 19.625 - 12.5 = 7.125 ឯកតាផ្ទៃ (1 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11345, 'ក្រុមហ៊ុនមួយចង់បង្កើនប្រាក់ចំណេញ \(P = 60x + 40y\) (ដុល្លារ) ដោយ \(x\) និង \(y\) ផ្ទៀងផ្ទាត់ ៖
\(\begin{cases} 2x + y \le 100 \\ x + y \le 80 \\ x \ge 0, \ y \ge 0 \end{cases}\)។
ក. កំណត់កំពូលនៃដែនចម្លើយពហុកោណ។
ខ. រកចំនួនផលិតផល \(x\) និង \(y\) ដែលផ្តល់ប្រាក់ចំណេញអតិបរមា ព្រមទាំងគណនាប្រាក់ចំណេញនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'រកប្រសព្វបន្ទាត់ទាំងពីរ: (2x+y) - (x+y) = 100 - 80 នាំឱ្យ x = 20, y = 60 (1.5 ពិន្ទុ)
កំណត់កំពូលទាំងបួនគឺ O(0, 0), A(50, 0), B(20, 60), C(0, 80) (1 ពិន្ទុ)
គណនា P(O) = 0; P(A) = 60(50) = 3,000 ដុល្លារ (0.5 ពិន្ទុ)
គណនា P(B) = 60(20) + 40(60) = 1,200 + 2,400 = 3,600 ដុល្លារ; P(C) = 40(80) = 3,200 ដុល្លារ (1 ពិន្ទុ)
សន្និដ្ឋានថាត្រូវផលិត x = 20 និង y = 60 ដើម្បីទទួលបានប្រាក់ចំណេញអតិបរមា 3,600 ដុល្លារ (1 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'hard', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11346, 'សិប្បកម្មផលិតគ្រឿងសង្ហារិមមួយផលិតតុ \(x\) និងកៅអី \(y\) ក្នុងមួយសប្តាហ៍។
តុមួយត្រូវការឈើ 3 ម៉ែត្រការេ និងកម្លាំងពលកម្ម 2 ម៉ោង។ កៅអីមួយត្រូវការឈើ 1 ម៉ែត្រការេ និងកម្លាំង 2 ម៉ោង។
ក្នុងមួយសប្តាហ៍សិប្បកម្មមានឈើយ៉ាងច្រើន 18 ម៉ែត្រការេ និងកម្លាំងពលកម្មយ៉ាងច្រើន 20 ម៉ោង។
ក. សរសេរប្រព័ន្ធវិសមីការកម្រិតធនធានឈើនិងកម្លាំងពលកម្ម។
ខ. បើតុមួយចំណេញ 50 ដុល្លារ និងកៅអីមួយចំណេញ 30 ដុល្លារ រកចំនួនតុនិងកៅអីដែលត្រូវផលិតដើម្បីបានប្រាក់ចំណេញខ្ពស់បំផុត។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរប្រព័ន្ធវិសមីការ: 3x + y <= 18 (ឈើ), 2x + 2y <= 20 នាំឱ្យ x + y <= 10 (កម្លាំង), x >= 0, y >= 0 (1.5 ពិន្ទុ)
រកប្រសព្វបន្ទាត់ទាំងពីរ: (3x + y) - (x + y) = 18 - 10 នាំឱ្យ 2x = 8 នាំឱ្យ x = 4, y = 6 (1 ពិន្ទុ)
កំណត់កំពូលទាំងបួន: O(0, 0), A(6, 0), B(4, 6), C(0, 10) (1 ពិន្ទុ)
