សន្និដ្ឋានថាត្រូវផលិតតុ 4 និងកៅអី 6 ដើម្បីចំណេញអតិបរមា 380 ដុល្លារក្នុងមួយសប្តាហ៍ (0.5 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11347, 'កសិដ្ឋានចិញ្ចឹមសត្វមួយត្រូវការលាយចំណីពីរប្រភេទ X និង Y សម្រាប់សត្វពាហនៈ។
