គណនាចំណាយ C = 2x + 3y: C(0, 8)=24; C(3, 2)=2(3)+3(2)=12; C(7, 0)=14 (1 ពិន្ទុ)
សន្និដ្ឋានថាត្រូវទិញចំណី X ចំនួន 3 kg និង Y ចំនួន 2 kg ដើម្បីចំណាយទាបបំផុត 12 ដុល្លារក្នុងមួយថ្ងៃ (0.5 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11348, 'ក្រុមហ៊ុនដឹកជញ្ជូនមួយត្រូវដឹកទំនិញ 120 តោន។ គេមានរថយន្តពីរប្រភេទ ៖ ប្រភេទ A អាចដឹកបាន 6 តោនក្នុងមួយជើង និងចំណាយថ្លៃសាំង 40 ដុល្លារ; ប្រភេទ B អាចដឹកបាន 10 តោនក្នុងមួយជើង និងចំណាយថ្លៃសាំង 60 ដុល្លារ។
ដោយសារកិច្ចសន្យា ក្រុមហ៊ុនត្រូវរត់យ៉ាងហោចណាស់ 14 ជើងសរុប។
ក. សរសេរប្រព័ន្ធវិសមីការនៃចំនួនជើងរត់ \(x\) (ប្រភេទ A) និង \(y\) (ប្រភេទ B)។
ខ. រកចំនួនជើងរត់នៃរថយន្តនីមួយៗដើម្បីឱ្យការចំណាយថ្លៃសាំងសរុបតិចបំផុត។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរប្រព័ន្ធ: 6x + 10y >= 120 (3x + 5y >= 60), x + y >= 14, x >= 0, y >= 0 (1.5 ពិន្ទុ)
