សន្និដ្ឋានថាត្រូវរត់រថយន្ត A ចំនួន 5 ជើង និងរថយន្ត B ចំនួន 9 ជើង ដើម្បីចំណាយតិចបំផុត 740 ដុល្លារ (0.5 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11349, 'កសិករម្នាក់មានដី 10 ហិកតាសម្រាប់ដាំដំណាំពីរមុខ ៖ ដំឡូងមី \(x\) ហិកតា និងសណ្តែកបាយ \(y\) ហិកតា។
ដើមទុនដាំដំឡូងមីគឺ 200 ដុល្លារ/ha និងសណ្តែកបាយ 100 ដុល្លារ/ha ដោយគាត់មានដើមទុនសរុបយ៉ាងច្រើន 1,600 ដុល្លារ។
ក. សរសេរប្រព័ន្ធវិសមីការតំណាងឱ្យដែនដី និងដើមទុន។
ខ. បើដំឡូងមីចំណេញ 300 ដុល្លារ/ha និងសណ្តែកបាយចំណេញ 200 ដុល្លារ/ha រកផែនការដាំដុះដែលផ្តល់ប្រាក់ចំណេញច្រើនបំផុត។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរប្រព័ន្ធវិសមីការ: x + y <= 10 (ដី), 200x + 100y <= 1600 នាំឱ្យ 2x + y <= 16 (ដើមទុន), x >= 0, y >= 0 (1.5 ពិន្ទុ)
រកប្រសព្វបន្ទាត់ទាំងពីរ: (2x+y) - (x+y) = 16 - 10 នាំឱ្យ x = 6, y = 4 (1 ពិន្ទុ)
កំណត់កំពូលទាំងបួន: O(0, 0), A(8, 0), B(6, 4), C(0, 10) (1 ពិន្ទុ)
គណនាចំណេញ P = 300x + 200y: P(A)=2400; P(B)=300(6)+200(4)=1800+800=2600; P(C)=2000 (1 ពិន្ទុ)
សន្និដ្ឋានថាត្រូវដាំដំឡូងមី 6 ហិកតា និងសណ្តែកបាយ 4 ហិកតា ដើម្បីទទួលបានប្រាក់ចំណេញអតិបរមា 2,600 ដុល្លារ (0.5 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 11350, 'សិស្សានុសិស្សមួយក្រុមរៀបចំធ្វើនំខេកលក់ក្នុងពិធីបុណ្យសាលា ដោយមានម្សៅសរុប 5000g និងស្ករស 3000g។
នំប្រភេទទីមួយត្រូវការម្សៅ 250g និងស្ករ 100g រីឯនំប្រភេទទីពីរត្រូវការម្សៅ 200g និងស្ករ 150g។
ក. សរសេរប្រព័ន្ធវិសមីការកំណត់ចំនួននំប្រភេទទីមួយ \(x\) និងប្រភេទទីពីរ \(y\)។
ខ. បើនំប្រភេទទីមួយលក់ចំណេញ 2 ដុល្លារ និងប្រភេទទីពីរចំណេញ 2.5 ដុល្លារ រកចំនួននំនីមួយៗដែលត្រូវធ្វើដើម្បីបានប្រាក់ចំណេញអតិបរមា។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរប្រព័ន្ធ: 250x + 200y <= 5000 (5x + 4y <= 100), 100x + 150y <= 3000 (2x + 3y <= 60), x >= 0, y >= 0 (1.5 ពិន្ទុ)
រកប្រសព្វ: 2(5x+4y) - 5(2x+3y) = 200 - 300 នាំឱ្យ -7y = -100 (មិនដាច់) ឬដោះស្រាយ 10x+8y=200, 10x+15y=300 នាំឱ្យ 7y=100 នាំឱ្យ y ≈ 14.28, x ≈ 8.57 (1 ពិន្ទុ)
ពិនិត្យចំណុចចំនួនគត់ក្បែរប្រសព្វ: (8, 14) នាំឱ្យ 5(8)+4(14)=40+56=96 <= 100 និង 2(8)+3(14)=16+42=58 <= 60 (1 ពិន្ទុ)
គណនាចំណេញ: P(8, 14) = 2(8) + 2.5(14) = 16 + 35 = 51 ដុល្លារ; P(0, 20) = 50; P(20, 0) = 40 (1 ពិន្ទុ)
សន្និដ្ឋានថាត្រូវធ្វើនំទីមួយ 8 នំ និងនំទីពីរ 14 នំ ដើម្បីទទួលបានប្រាក់ចំណេញអតិបរមា 51 ដុល្លារ (0.5 ពិន្ទុ)', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'pisa', 0, '10', 'ការដោះស្រាយវិសមីការតាមក្រាប', 'ជំពូកទី 4 : ធរណីមាត្រក្នុងប្លង់', NULL, 0);
